// Strings: a modelled cello (and later a violin), measured from recordings.
//
// A note is the cello's recorded onset (the bow's catch, its scratch and its pitch glide, 0.3 s)
// handing over to a model: a bank of harmonics whose steady spectrum is source x body, kept alive by
// the bow's own movement as measured (pitch, level and each harmonic wandering), with the bow's
// noise in octave bands pulsing at the string's period, and a release that lets each harmonic ring
// down at the rate measured from the staccatos. Everything comes from src/CelloData.h, generated by
// tools/analyze.py and tools/make_header.py; docs/MODEL.md says how.
#include <synthkit/synth.h>

#include <climits>
#include <cmath>
#include <cstdint>
#include <cstring>

#include "CelloData.h"
#include "PizzData.h"
#include "StaccData.h"
#include "TouchData.h"
#include "UpbowData.h"

using namespace sk;
namespace cd = cello_data;
namespace pd = pizz_data;
namespace sd = stacc_data;
static_assert(sd::kNotes == cd::kNotes, "the staccatos are measured at the sustains' notes");
static_assert(upbow_data::kNotes == cd::kNotes && upbow_data::kOnsetRate == cd::kOnsetRate,
              "the up-bow onsets are measured at the sustains' notes and rate");

namespace {

constexpr int kMaxHarm = cd::kHarm;
constexpr int kGrid = 32;               // the voice's own step (samples of its time): wander, glide, release
constexpr float kGlideS = 0.15f;        // from the onset's harmonics to the steady spectrum
constexpr float kLifeInS = 0.3f;        // the bow's movement comes in over this, from the hand-off's end
constexpr float kOnsetReleaseDbS = 80;  // the onset recording, if a key is let go during it
constexpr float kNoiseReleaseS = 0.015f;
constexpr float kCorrSpan = 3;          // a measured note's own correction fades out over this many semitones
constexpr float kEndDb = -96;
constexpr float kTrimDb = -6;           // headroom: four strings at f peak near 0 dBFS at the recordings' level
constexpr int kFlickBands = 3;          // a harmonic's own movement: three two-octave bands, 0.25-16 Hz
constexpr int kFlickEvery = 4;
// The level moves only slowly: the recordings' level also moves 0.2-0.3 dB per octave at 2-16 Hz,
// but played alone (not tied to the rest of the bow's change) that is a random volume jitter (the
// owner heard it so). A judgment: its octaves from 2 Hz up are left out, and a low-pass at 3 Hz
// closes the slower bands' skirts.
constexpr int kLevelOcts = 3;           // 0.25-2 Hz
constexpr float kLevelLpHz = 3;          // ... updated every 4th step (345 Hz at 44.1 kHz: 17× its 20 Hz top)
constexpr int kGrainTable = 64;
constexpr float kLn10_20 = 0.11512925f; // ln(10) / 20
constexpr float kRecomputeRatio = 1.7345e-3f;  // the spectrum follows the pitch past 3 cents (its detail is 50)
constexpr float kFollowS = 0.03f;       // after the first glide, the harmonics follow the dynamic and pitch this fast
constexpr float kRebowS = 0.01f;        // a string bowed again while it sounds: what it played fades over this
constexpr float kDynRecompute = 0.01f;  // the spectrum follows the dynamic past this much of a layer
constexpr float kLog2_10_20 = 0.16609640f;  // log2(10) / 20
// The cello's open strings (C2 G2 D3 A3). A note is played on the highest string tuned below it (an
// open string's note on the next one down, as a player does to give it vibrato); the lowest notes on C.
constexpr int kStrings = 4;
constexpr int kOpen[kStrings] = {36, 43, 50, 57};
int stringFor(double midi) {
  int s = 0;
  for (int c = 1; c < kStrings; ++c)
    if (kOpen[c] < midi - 0.5) s = c;
  return s;
}
// Vibrato (a judgment, from cellists' measured vibrato: about 5.3-6.5 Hz, 10-17.5 cents either side,
// wider in cents up the string, where the same movement of the finger is a larger share of the
// string's length): the depth given is for a note a fifth above its open string, scaled by the
// string's length there (1/L: 2^(semitones/12)), between the open string and two and a half octaves
// up it.
constexpr float kVibRefSemis = 7;
constexpr float kVibVaryRate = 0.12f;   // at Vary 100 %: the rate wanders by this (rms share)
constexpr float kVibVaryDepth = 0.5f;   // ... and the depth by this
constexpr float kVibVaryHz = 1.0f;      // how fast they wander (one-pole)
constexpr float kVibFollowS = 0.025f;   // the depth follows its envelope this fast (a slur: the finger lifts)
// After a slur the vibrato starts again sooner than on a new bow (the hand is already moving): a share
// of Delay and Attack; its cycle starts from zero once the depth has faded (the finger has landed).
constexpr float kVibSlurDelay = 0.25f, kVibSlurAttack = 0.4f;
// A slur's articulation (a judgment: the recordings have none): the note dips as the finger moves and
// lands, the bow going on (its noise doesn't dip). At Slur 100 %: down by kSlurDb over kSlurFallS,
// held kSlurHoldS, back over kSlurRiseS; less is shallower and shorter.
constexpr float kSlurDb = 12, kSlurFallS = 0.015f, kSlurHoldS = 0.05f, kSlurRiseS = 0.07f;
// Bow Weight: the source spectrum of a lighter or heavier bow, along the recordings' own dynamics (in
// bowed strings the brightness follows the bow's force, the level mostly its speed), at the level the
// dynamic plays. ±100 % is ±1.5 layers, taken past p and f by half a layer at most (extrapolated).
constexpr float kWeightLayers = 1.5f;
// The room (synthkit's dsp::Reverb, from 10d6/piano): its level, twice the piano's (a held note
// masks its own room, where a piano's decay lets it through: at the piano's level, Reverb 20 % was
// 19 dB under a held note). At the default, 25 %, the room is about 11 dB under a held note; at
// 100 %, about as loud as it. The spaces are levelled against each other for an impulse through a
// one-pole low-pass at 800 Hz (about a cello's spectrum, as a piano's).
constexpr float kWet = 2 * 0.1062f;
constexpr float kRoomWeightHz = 800.f;
constexpr float kRoomDefault = 25;
// Sympathetic strings (the piano's free-string bank, for four open strings): each open string's
// partials up to kSympFMax as narrow resonators, decaying at the string's measured release rate,
// driven by everything the cello plays (the dry sound) through the bridge. A string a note is
// played on is stopped by the finger: damped, not driven. tools/sympathy.py measures the ringing in
// the staccatos' releases, and kSympK is calibrated to it (docs/MODEL.md: Sympathetic strings).
constexpr int kSympMax = 96;
constexpr float kSympFMax = 2000;
constexpr float kSympDampDbS = 300;     // a stopped string's open modes: gone in a third of a second
// The drive: z += kSympK x / fs. A judgment: a note with no harmonic in unison with an open partial
// rings the free strings 42 dB under itself while held; one in unison (G3 on the open G) about 25 dB
// under. The recorded cello's own sympathetic ring is already in its measured spectra: at 12 dB more
// the bank moved the distance from the recordings (4.2 → 4.5 %), at this it doesn't. The staccatos'
// late ring (tools/sympathy.py) would need 42 dB more, which makes held notes ring as loud as
// themselves: a sound-driven bank can't give both (docs/MODEL.md).
constexpr float kSympK = 0.55f;
// Body Size: a body larger by λ has its resonances lower by λ, so the body (its fit, the measured
// notes' corrections and its fine detail) is read at f·λ. The string and its source spectrum stay.
// The wolf (a judgment: none of the recordings has one): where the body's main resonance couples
// with the string's fundamental, the note can't settle and its level stutters. Near the wolf note
// (a Gaussian in cents, kWolfWidthC wide) the tone dips by up to kWolfDb × Wolf, kWolfHz times a
// second (faster the nearer), its rate wandering.
constexpr float kWolfWidthC = 35, kWolfDb = 14, kWolfHz = 7;
// Bow Position (a judgment, from bowed-string acoustics: none of the recordings has it). The bowing
// point β (a share of the string from the bridge) goes from 1/4 (sul tasto, −100 %) through 1/10
// (normal) to 1/40 (sul ponticello, +100 %). Players slow the bow and press harder near the bridge,
// which is most of its brilliance: the source moves along the recordings' own dynamics by
// kPosLayers. The partials with a node at the bowing point are weakened (to kPosNodeFloor, the bow's
// width filling the rest), the more the further from normal. Past what the dynamics reach, a tilt:
// glassy near the bridge (the fundamental weaker, the upper partials stronger), soft over the
// fingerboard; and the bow noise grows at both ends, scratchy at the bridge, airy over the fingerboard.
constexpr float kPosLayers = 1.0f, kPosNodeFloor = 0.3f;
constexpr float kPosBeta0 = 0.1f, kPosBridge = 4.f, kPosTasto = 2.5f;
constexpr float kPosNoiseBridgeDb = 8, kPosNoiseTastoDb = 6;
// The mute (a judgment, from measurements of violin mutes: every mute dips the bridge's resonance
// region, a heavy one deeper and wider, and takes the lows and the loudness too). 50 % is about a
// performance mute, 100 % a heavy practice mute. Not normalised back to the level: a mute is quieter.
constexpr float kMuteHillHz = 1800, kMuteHillOct = 0.8f, kMuteHillDb = 12, kMuteHighDb = 6, kMuteHeavyDb = 6;

// Articulations (the Articulation choice, and keyswitches below the cello's range). A voice reads its
// note's articulation as it starts (processEvents records it per key): changing it during a note
// affects the next.
// (Appended as they came, so patches keep their indices.)
enum Art { kArco = 0, kPizz = 1, kStacc = 2, kSpicc = 3, kTrem = 4, kHarmonic = 5 };
// The strokes the bow ends by itself, whatever the key does.
inline bool isStroke(int a) { return a == kStacc || a == kSpicc; }
// Keyswitches, white keys an octave below the cello's C2: C1 Arco, D1 Staccato, E1 Spiccato,
// F1 Pizzicato, G1 Tremolo, A1 Harmonics. They're swallowed: they don't sound.
constexpr int kKeySwitch[][2] = {{24, kArco}, {26, kStacc}, {28, kSpicc}, {29, kPizz}, {31, kTrem}, {33, kHarmonic}};
// Spiccato (a judgment, from the staccatos: docs/MODEL.md): the take one dynamic lighter, its level at
// the bounce this far under the staccato's stroke at the same velocity.
constexpr float kSpiccDb = 3;
// Harmonics (docs/MODEL.md: Harmonics): a note is a natural harmonic of an open string where one
// sounds at its key (nodes 2-6, within half a semitone), else an artificial one (a stopped note touched
// a fourth above: node 4; then a fifth, 3; then an octave, 2) on the lowest string it fits; below C3
// none fits, and the note is bowed as usual. Its k-th harmonic is the string's n·k-th: the bowed
// source read there, less what the finger takes (tools/touch.py), the body at k times the pitch as
// always, kLevelDb under a bowed note. No recording starts it: it swells in over kHarmAttackS (a
// judgment) from the steady spectrum.
constexpr float kHarmAttackS = 0.08f;
int harmonicNode(double midi) {
  constexpr int open[4] = {36, 43, 50, 57};
  for (int n = 2; n <= 6; ++n)
    for (int o : open)
      if (std::fabs(midi - (o + 12.0 * std::log2(static_cast<double>(n)))) <= 0.5) return n;
  for (int n : {4, 3, 2})
    if (midi - 12.0 * std::log2(static_cast<double>(n)) >= 36.0 - 1e-6) return n;
  return 1;
}
// Tremolo (docs/TREMOLO.md: the experiments that led here): the bow's strokes as recorded. Each stroke is
// one of bigcat's staccato takes bowed that way (its round robins alternate bows; tools/staccato.py reads
// which way each went), from where its stroke starts, transposed to the note, at a dynamic within
// kTremDynSpread of the note's, its early part (a tremolo's stroke never gets further) at a held note's
// level for the dynamic (a staccato's peak is ~11 dB over that, its early part about at it), and
// kTremLevelDb rms of its own; kTremTrimDb brings the tremolo's rms to a held note's (it read 2.6 dB over
// it, median over C2-C6 at two velocities: the takes' noise and their peakier strokes). A bow change turns the string's motion
// over, so the new stroke is lined up with the old at half a cycle of the fundamental, crossfading over
// kTremXfMinS-kTremXfMaxS. The rhythm is a solo cellist's (the Philharmonia Orchestra's cello tremolos,
// measured only: their licence lets nothing of them ship): changes jittered around a beat (kTremJitter
// rms, so a long stroke is followed by a short), each stroke kTremWobble more, the beat drifting over a
// few strokes (kTremDrift, kTremDriftPole), one bow kTremAlt longer. Stroke lengths vary 12-18 % rms, as
// his did; perfectly even strokes sounded mechanical to the owner. Letting go ends the stroke under way;
// the model's release rings on from there, crossfading in over kTremEndXfS.
constexpr float kTremDynSpread = 1.f, kTremLevelDb = 1.8f, kTremTrimDb = -2.6f;
constexpr float kTremJitter = 0.066f, kTremWobble = 0.076f, kTremDrift = 0.03f, kTremDriftPole = 0.8f, kTremAlt = 0.04f;
constexpr float kTremMinLen = 0.6f, kTremMaxLen = 1.45f;   // a stroke's length, as a share of the beat
constexpr float kTremXfMinS = 0.006f, kTremXfMaxS = 0.012f, kTremEndXfS = 0.01f;
constexpr float kUnitSd = 1.7320508f;   // a bipolar draw times this has unit variance
constexpr long kNever = LONG_MAX / 2;   // "not yet" (a long is 32 bits in the browser: 6 hours at 48 kHz)
int keyswitchArt(int note) {
  for (const auto& k : kKeySwitch)
    if (k[0] == note) return k[1];
  return -1;
}
// Pizzicato (tools/pizz.py, docs/MODEL.md: Pizzicato). The pluck as recorded, then the string's
// harmonics ringing down as measured modes. Velocity scales the level by v² as the library's own sfz
// maps it (no layers: the four round robins span no dynamic); a softer pluck is also darker, a
// judgment: a first-order high shelf above kPizzShelfHz, down by kPizzShelfDb × (1 − v).
constexpr float kPizzShelfHz = 1200, kPizzShelfDb = 12;
// Letting go of the key lifts the finger, which damps the string: on top of its own decay (a judgment;
// Release scales it, and the sustain pedal holds it off, so it rings as measured).
constexpr float kPizzDampDbS = 60;
constexpr float kNeperDb = 8.6858896f;   // dB per neper

// e^x for gains: 2^f by a 5th-order polynomial (relative error ~2e-7), the exponent in the bits.
// The browser's expf is a software routine, and this runs per harmonic per step.
inline float fastExp(float x) {
  x = dsp::clamp(x, -80.f, 80.f);
  float t = x * 1.44269504f;
  float fi = std::floor(t), f = t - fi;
  float p = 1.f + f * (0.69314718f + f * (0.24022651f + f * (0.05550411f + f * (0.00961813f + f * 0.00133336f))));
  int32_t bits = (static_cast<int32_t>(fi) + 127) << 23;
  float scale;
  std::memcpy(&scale, &bits, sizeof scale);
  return p * scale;
}

// 2^x, the same polynomial as fastExp
inline float fastExp2(float x) { return fastExp(x * 0.69314718f); }

// log2(x) for x > 0: the exponent from the bits, the mantissa by a 4th-order polynomial (~1e-4)
inline float fastLog2(float x) {
  int32_t bits;
  std::memcpy(&bits, &x, sizeof bits);
  float e = static_cast<float>(((bits >> 23) & 255) - 127);
  bits = (bits & 0x007FFFFF) | 0x3F800000;
  float m;
  std::memcpy(&m, &bits, sizeof m);   // 1 ≤ m < 2
  float t = m - 1;
  return e + t * (1.44269504f + t * (-0.72134752f + t * (0.45689917f + t * -0.18326905f)));
}

// log2 of each harmonic number, so a harmonic's log-frequency is one add
struct Log2K {
  float v[cd::kHarm];
  Log2K() { for (int k = 0; k < cd::kHarm; ++k) v[k] = std::log2(float(k + 1)); }
};
const Log2K kLog2K;

// Velocity (0-1) to the dynamic axis: 0 p, 1 mp, 2 mf, 3 f, as the library's sfz maps its layers
// (1-32 p, 33-64 mp, 65-96 mf, 97-127 f: each layer's middle velocity plays it).
float dynOf(float vel) { return dsp::clamp((vel * 127.f - 16.f) / 32.f, 0.f, 3.f); }

float bodyDbLog2(float l2) {
  float x = (l2 - cd::kKnot0) * (1.f / cd::kKnotStep);
  if (x <= 0) return cd::body[0];
  if (x >= cd::kKnots - 1) return cd::body[cd::kKnots - 1];
  int i = static_cast<int>(x);
  float t = x - i;
  return cd::body[i] + t * (cd::body[i + 1] - cd::body[i]);
}

// The body's fine detail (dB) at log2(f): narrow resonances the fitted body's 50-cent knots smooth
// over (tools/finebody.py). Read every step, so a vibrato sweeps the harmonics through it.
inline float fineDbLog2(float l2) {
  float x = (l2 - cd::kKnot0) * (1.f / cd::kFineStep);
  if (x <= 0) return 0.01f * cd::fine[0];
  if (x >= cd::kFine - 1) return 0.01f * cd::fine[cd::kFine - 1];
  int i = static_cast<int>(x);
  float t = x - i;
  return 0.01f * (cd::fine[i] + t * (cd::fine[i + 1] - cd::fine[i]));
}

struct InvFitF0 {
  float v[cd::kNotes][cd::kDyns];
  InvFitF0() { for (int n = 0; n < cd::kNotes; ++n) for (int d = 0; d < cd::kDyns; ++d) v[n][d] = 1.f / cd::fitF0[n][d]; }
};
const InvFitF0 kInvFitF0;

// A measured cell's correction at frequency hz (dB), read along its own harmonics.
float corrDb(int note, int dyn, float hz) {
  float x = hz * kInvFitF0.v[note][dyn] - 1;
  if (x < 0 || x >= cd::kHarm - 1) return 0;
  int i = static_cast<int>(x);
  float t = x - i;
  return 0.01f * (cd::corr[note][dyn][i] + t * (cd::corr[note][dyn][i + 1] - cd::corr[note][dyn][i]));
}

// Where a pitch (fractional MIDI) falls among the measured notes: the lower one and the way to the next.
void bracket(double midi, int& lo, float& t) {
  if (midi <= cd::noteMidi[0]) { lo = 0; t = 0; return; }
  if (midi >= cd::noteMidi[cd::kNotes - 1]) { lo = cd::kNotes - 2; t = 1; return; }
  lo = 0;
  while (lo < cd::kNotes - 2 && midi >= cd::noteMidi[lo + 1]) ++lo;
  t = static_cast<float>((midi - cd::noteMidi[lo]) / (cd::noteMidi[lo + 1] - cd::noteMidi[lo]));
}

// A value per (note, dynamic), interpolated in both.
template <typename F>
float cellLerp(int lo, float tn, float dyn, F get) {
  int d0 = std::min(static_cast<int>(dyn), cd::kDyns - 2);
  float td = dyn - d0;
  auto at = [&](int n) { return get(n, d0) + td * (get(n, d0 + 1) - get(n, d0)); };
  return at(lo) + tn * (at(lo + 1) - at(lo));
}

// RBJ band-pass, constant 0 dB peak (the bow noise's, as tools/make_header.py solves against; and the
// wander's octave bands).
struct BandPass {
  float b0 = 0, b2 = 0, a1 = 0, a2 = 0, z1 = 0, z2 = 0;
  void set(float fc, float q, float sr) {
    fc = std::min(fc, 0.45f * sr);
    float w = dsp::kTwoPi * fc / sr, al = std::sin(w) / (2 * q), a0 = 1 + al;
    b0 = al / a0; b2 = -al / a0; a1 = -2 * std::cos(w) / a0; a2 = (1 - al) / a0;
  }
  float process(float x) {
    float y = b0 * x + z1;
    z1 = -a1 * y + z2;
    z2 = b2 * x - a2 * y;
    return y;
  }
  void reset() { z1 = z2 = 0; }
};

// RBJ low-pass (Q 0.707): it closes a harmonic's own movement above 20 Hz, where a band-pass's
// 6 dB/octave skirt would leave sidebands 20-30 dB under each harmonic, over the bow noise between
// them (and over its pulse, which tools/life.py found the recordings have).
struct LowPass {
  float b0 = 0, b1 = 0, b2 = 0, a1 = 0, a2 = 0, z1 = 0, z2 = 0;
  void set(float fc, float sr) {
    fc = std::min(fc, 0.45f * sr);
    float w = dsp::kTwoPi * fc / sr, al = std::sin(w) / (2 * 0.70710678f), c = std::cos(w), a0 = 1 + al;
    b0 = (1 - c) / 2 / a0; b1 = (1 - c) / a0; b2 = b0; a1 = -2 * c / a0; a2 = (1 - al) / a0;
  }
  float process(float x) {
    float y = b0 * x + z1;
    z1 = b1 * x - a1 * y + z2;
    z2 = b2 * x - a2 * y;
    return y;
  }
  void reset() { z1 = z2 = 0; }
};
constexpr float kFlickLpHz = 20;

// The rms a BandPass (then, optionally, a LowPass) gives for unit-variance white noise.
float noiseRms(BandPass f, const LowPass* lp = nullptr) {
  f.reset();
  LowPass l;
  if (lp) l = *lp, l.reset();
  double e = 0;
  float x = 1;
  for (int i = 0; i < 12000; ++i) {   // 13 energy e-folds of the slowest (0.35 Hz) band
    float y = f.process(x);
    if (lp) y = l.process(y);
    x = 0;
    e += double(y) * y;
  }
  return static_cast<float>(std::sqrt(e));
}

// A BandPass driven by unit white noise, in its steady state: the covariance of its two state
// variables (sum over its impulse response of s s^T), as a 2x2 Cholesky factor. Starting a filter
// from a draw of it means the slow wander (1-2 s to build up from rest) moves fully from the start.
struct Stationary {
  float l11 = 0, l21 = 0, l22 = 0;
  void of(const BandPass& f) {
    // DF2T: s' = A s + B x, A = [[-a1, 1], [-a2, 0]], B = [-a1 b0, b2 - a2 b0]
    const double a1 = f.a1, a2 = f.a2, b0 = f.b0, b2 = f.b2;  // widen before multiplying
    double s1 = -a1 * b0, s2 = b2 - a2 * b0, p11 = 0, p12 = 0, p22 = 0;
    for (int i = 0; i < 12000; ++i) {
      p11 += s1 * s1; p12 += s1 * s2; p22 += s2 * s2;
      double n1 = -a1 * s1 + s2, n2 = -a2 * s1;
      s1 = n1; s2 = n2;
    }
    l11 = static_cast<float>(std::sqrt(p11));
    l21 = l11 > 0 ? static_cast<float>(p12 / l11) : 0.f;
    l22 = static_cast<float>(std::sqrt(std::max(0.0, p22 - double(l21) * l21)));
  }
  void draw(BandPass& f, dsp::Rng& r) const {
    float u = r.normal(), v = r.normal();
    f.z1 = l11 * u;
    f.z2 = l21 * u + l22 * v;
  }
};

}  // namespace

struct Strings;

struct StringsVoice : Voice {
  explicit StringsVoice(Strings& s) : synth(s) {}
  void prepare(const PrepareInfo& info) override;
  void start(const NoteOn& n, const StartInfo& s) override;
  void release() override { releasing = true; }
  void render(VoiceContext& ctx, Buffer& out) override;
  bool active() const override { return alive; }

  void setup(VoiceContext& ctx);
  void place(float hz);               // what depends on where the pitch is and the dynamic
  void extend(int k1);                // more harmonics, as the pitch falls
  void setRotation(float hz);
  void spectrum(float hz);            // the steady spectrum's targets at this pitch
  void grainShape(float amount);      // the noise pulse's tables
  void step(VoiceContext& ctx);       // one kGrid step of the voice's own time
  void stepBank(float f);
  void setupStroke(double midi, float hz, int on, int od);
  void tuneWander(float speed);
  void tuneHarm(int k, float speed);
  float wanderOctaves(BandPass* f, const float* rms, float scale);
  float sustainDyn() const;
  float posDb(int n) const;
  float muteDb(float f) const;
  float levelAt(int lo, float tn, float d) const;

  Strings& synth;
  float sr = 48000;
  bool pending = false, alive = false, releasing = false, released = false;
  float vel = 0, velDyn = 0, dyn = 0;
  long t = 0;                         // samples since the note started
  uint64_t seedNoise = 1, seedWander = 1, seedVib = 1;

  // a string bowed again while it sounds (or a voice taken): the old sound fades, then the note starts
  bool restart = false;
  int fadeLeft = 0, fadeLen = 1;
  float nextVel = 0;
  uint64_t nextSeeds[3] = {1, 1, 1};

  // which string, and a slur within it (another key taking the string while it is bowed)
  int string = 0, assigned = -1, curString = 0;
  float slurC = 0, slurRate = 0;
  double midiNow = 0, slurFrom = 0;
  bool slurPending = false;

  // where the note sits among the measured ones (for the pitch and dynamic it has now)
  int lo = 0, d0 = 0;
  float tn = 0, td = 0, wLo = 0, wHi = 0, level = 0;
  float placeHz = 0, placeDyn = -1, placeWeight = 0, placeEven = 1;

  // the onset: which recording, where in it, how fast it is read
  const short* onset = nullptr;
  int onsetLen = 0;
  long bowOff = -1;   // a stroke's bow leaves here (note samples), whatever the key does
  float strokeRel[kMaxHarm];   // a stroke's own release, per harmonic (ln gain per sample)
  float strokeFade = 0;        // a long stroke's fade before its bow leaves (ln gain per sample)
  int hNode = 1;               // a harmonic's node: its k-th harmonic is the string's hNode·k-th
  double pos = 0, step_ = 1, stepBase = 1;
  float hzOnset = 1;
  float onsetGain = 0, onsetRel = 1, onsetRelMul = 1;
  long tX0 = 0, tX1 = 0, tC = 0;      // the crossfade and the hand-off instant, in samples

  // the model
  int K = 0;
  bool bankOn = false;
  float zr[kMaxHarm], zi[kMaxHarm], rc[kMaxHarm], rs[kMaxHarm];
  float amp[kMaxHarm], target[kMaxHarm], gain[kMaxHarm], relRate[kMaxHarm];
  float fineL2[kMaxHarm];             // this step's fine detail per harmonic (log2 of its gain)

  float srcDb[kMaxHarm];              // source part of the steady spectrum (per dynamic)
  float hand[kMaxHarm], handPh[kMaxHarm];
  float specHz = 0, specBody = -1;    // the pitch and Body the targets were computed for
  float glideRate = 0, followRate = 0;

  // the bow's movement (cents, dB), as band-limited noise per octave, on the kGrid step
  BandPass wPitch[cd::kOct], wLevel[cd::kOct], wHarm[kMaxHarm][kFlickBands];
  LowPass wHarmLp[kMaxHarm];
  LowPass wLevelLp;
  float rmsPitch[cd::kOct], rmsLevel[cd::kOct], rmsHarm[kFlickBands];
  // the harmonics' shared patterns (the recording's own): a shape over the harmonics and its score,
  // band-limited noise with the measured spectrum; and each harmonic's leftover, independent part
  BandPass wPat[cd::kPat][cd::kOct];
  LowPass wPatLp[cd::kPat];
  float rmsPat[cd::kPat][cd::kOct], score[cd::kPat];
  const float* shape[cd::kPat];
  const float* residK = nullptr;
  float normOct[cd::kOct], normFlick[kFlickBands];   // each filter's rms for unit noise
  Stationary statOct[cd::kOct], statFlick[kFlickBands];   // their steady states (at Speed 100 %)
  float flick[kMaxHarm];
  float wSpeed = -1;
  float pitchC = 0, levelDb = 0;
  dsp::Rng wrng;

  // vibrato: its phase, its time since the note began, and its slow irregularity
  float vibPh = 0, vibScale = 1, vibNormVary = 1, vibR = 0, vibD = 0, vibA = 0, vibDepth = 0;
  long vibT0 = 0;                     // when its envelope began: the note's start, or its last slur
  bool vibSlurred = false, vibRephase = false;
  // a slur's articulation: when it began (-1 none), and the tone's gain at this step and the last
  long artT0 = -1;
  float artGain = 1, artPrev = 1;
  bool slurArt = false;
  dsp::Rng vrng;
  dsp::Rng trng;            // the tremolo's rhythm: seeded by the block the note starts in (one bow for a double stop)
  dsp::Rng crng;            // ... and which take each stroke is: the note's own
  unsigned tremSeed = 0, nextTremSeed = 0;
  // the tremolo: two strokes (the one under way, and the last one fading at a change)
  struct TremGrain {
    const short* x = nullptr;
    int len = 0;
    double pos = 0;           // in the take's samples from where its stroke starts
    float stepK = 0, g = 0, f0 = 1, ph0 = 0;
  };
  TremGrain tg[2];
  int tgCur = 0, tremDir = 1, tremXfLen = 1, tremXfNext = 1, tremLast[2] = {-1, -1};
  long tremNext = 0, tremXfT0 = 0;
  float tremDrift = 0, tremJ = 0, tremAlt = 1, tremDb = 0, fNow = 0;
  bool tremStop = false, tremEven = false;

  // bow noise, pulsing at the string's period
  BandPass bp[cd::kBands][2];
  float noiseGain[cd::kBands];
  float grain[cd::kBands][kGrainTable + 1];
  float grainDepth[cd::kBands], grainPh[cd::kBands], grainAmount = -1, grainDepthAt = -1;
  float noiseDrive = 0, noiseRelMul = 1;
  dsp::Rng rng_;

  // parameter values for this render call
  float pLife = 1, pPitch = 1, pFlicker = 1, pSpeed = 1, pBody = 1, pNoiseDb = 0, pGrain = 1, pRelease = 1;
  float pTremRate = 12;
  float pDyn = 2, pVibDepth = 0, pVibRate = 5.5f, pVibDelay = 0.3f, pVibAttack = 0.5f, pVibVary = 0.4f, pGlide = 0;
  float pWeight = 0, pSlur = 0.5f, pEven = 1, pSize = 1, pWolf = 0, pWolfHz = 175, pPos = 0, pMute = 0;
  float placePos = 0, specMute = 0;
  float specSize = 1;
  float wolfPh = 0, wolfR = 0;
  bool pDynCtl = false;

  // the articulation this note plays (read as it starts), and the next one's (a string played again)
  int art = kArco, nextArt = kArco, rrSel = 0, nextRR = 0;
  bool upBow = false, nextUpBow = false;   // this bow starts up (Bowing: Alternate), from the up-bow take
  float energy = 0;
  float vibratoC(double midi);        // this step's vibrato (cents)
  int arcoRun(VoiceContext& ctx, Buffer& out, int i, int n);
  void arcoEnd(int n);
  void setupTrem();
  void tremStroke(long ti);
  void tremEnd();
  float tremSample(long ti);

  // pizzicato: the pluck as recorded, then the measured modes ringing down
  void setupPizz(VoiceContext& ctx);
  void stepPizz(VoiceContext& ctx);
  int pizzRun(VoiceContext& ctx, Buffer& out, int i, int n);
  void pizzEnd(int n);
  const short* pOnset = nullptr;
  int pN = 0;
  float pzr[pd::kMaxModes], pzi[pd::kMaxModes], prc[pd::kMaxModes], prs[pd::kMaxModes];
  float pc0[pd::kMaxModes], ps0[pd::kMaxModes], pOm[pd::kMaxModes], pPh[pd::kMaxModes];
  float pBase[pd::kMaxModes], pAlpha[pd::kMaxModes], pRecDb[pd::kMaxModes], pRecFine[pd::kMaxModes];
  float pL2k[pd::kMaxModes], pTarget[pd::kMaxModes];
  float pFRec = 1, pL2Rec = 0, pShelfG = 1, pShelfA = 0, pShelfZ = 0, pLevel = 0;
};

struct Strings : Synth {
  Param life, lifePitch, lifeFlicker, lifeSpeed, body, noise, grain, release;
  Param dynamics, dynMode, strings, vibDepth, vibRate, vibDelay, vibAttack, vibVary, weight, slur, even;
  Param glide, voiceMode;
  Param room, spaceType, spaceDecay, spaceSize, spacePredelay, spaceDamping, spaceEarly, spaceLowCut, spaceHighCut;
  Param resonance, a4, bodySize, wolf, wolfNote, bowPos, mute, articulation, tremRate, bowing;
  // per key, set in processEvents as its note goes to the voices: the articulation it plays (the
  // choice at that moment, after any keyswitch before it), and for pizzicato its round robin
  int noteArt[128] = {}, noteRR[128] = {};
  // and which way its bow goes (Bowing: Alternate turns the bow at each new bow; notes starting in the
  // same block share one; a slur in Legato keeps it). The first bow is a down-bow.
  bool noteUp[128] = {}, bowUp = true, keyDown[128] = {};
  unsigned bowBlock = ~0u;
  unsigned char rrNext[128] = {};
  // blocks seen: notes starting in the same block share a tremolo (one bow across a double stop)
  unsigned blocks = 0;
  // the sympathetic strings: per resonator its state, its turn per sample (free and damped), its string
  float symZr[kSympMax] = {}, symZi[kSympMax] = {}, symPr[kSympMax], symPi[kSympMax], symDr[kSympMax], symDi[kSympMax];
  float symRate[kSympMax];            // the free decay (dB/s)
  int symString[kSympMax], symK[kSympMax], symN = 0;
  float symA4 = -1, symSr = 48000;
  unsigned stopMask = 0;              // strings a voice played on this block (reported by the voices)

  // the room: the voices' sum (mono) in, the space's wet signal out, per control block
  dsp::Reverb reverb;
  float revIn[32], wetL[32], wetR[32];
  // set in processEvents (a parameter's value at the block's start) and allocateVoice, read by the
  // voice it starts: the string its note was given
  bool perString = false;
  int allocString = -1;

  void defineParams(ParamBuilder& b) override {
    life = b.add("life.amount").name("Life").range(0, 300).def(100).unit("%").modulatable();
    lifePitch = b.add("life.pitch").name("Pitch Wander").range(0, 400).def(100).unit("%").modulatable();
    lifeFlicker = b.add("life.flicker").name("Flicker").range(0, 400).def(100).unit("%").modulatable();
    lifeSpeed = b.add("life.speed").name("Speed").range(25, 400).log().def(100).unit("%").modulatable();
    body = b.add("tone.body").name("Body").range(0, 200).def(100).unit("%").modulatable();
    noise = b.add("tone.noise").name("Bow Noise").range(-30, 24).def(0).unit("dB").modulatable();
    grain = b.add("tone.grain").name("Grain").range(0, 300).def(100).unit("%").modulatable();
    release = b.add("play.release").name("Release").range(25, 400).log().def(100).unit("%").modulatable();
    articulation = b.add("play.articulation").name("Articulation")
                       .choices({"Arco", "Pizzicato", "Staccato", "Spiccato", "Tremolo", "Harmonics"});
    tremRate = b.add("play.tremRate").name("Tremolo Rate").range(6, 20).def(12).unit("Hz").modulatable();
    bowing = b.add("play.bowing").name("Bowing").choices({"Down Bows", "Alternate"}).def(1);
    dynMode = b.add("play.dynMode").name("Dynamics From").choices({"Velocity", "Controller"});
    dynamics = b.add("play.dynamics").name("Dynamics").range(0, 100).def(67).unit("%").smoothing(30)
                   .modulatable().cc(1).cc(11);
    strings = b.add("play.strings").name("Strings").choices({"Free", "One Note Each"});
    slur = b.add("play.slur").name("Slur").range(0, 100).def(50).unit("%").modulatable();
    even = b.add("play.even").name("Even Notes").range(0, 100).def(100).unit("%").modulatable();
    weight = b.add("bow.weight").name("Bow Weight").range(-100, 100).def(0).unit("%").modulatable();
    vibDepth = b.add("vib.depth").name("Vibrato").range(0, 50).def(0).unit("ct").modulatable();
    vibRate = b.add("vib.rate").name("Rate").range(3, 9).def(5.5).unit("Hz").modulatable();
    vibDelay = b.add("vib.delay").name("Delay").range(0, 2).def(0.3).unit("s");
    vibAttack = b.add("vib.attack").name("Attack").range(0.05, 3).log().def(0.5).unit("s");
    vibVary = b.add("vib.vary").name("Vary").range(0, 100).def(40).unit("%").modulatable();
    // the room (the piano's Space controls, the same IDs and ranges): the recordings are dry and
    // close-miked, which is part of why the tone sounds edgy; a hall around it is what a listener hears
    room = b.add("space.room").name("Reverb").range(0, 100).def(kRoomDefault).unit("%").modulatable().group("Space");
    spaceType = b.add("space.type").name("Space").choices({"Room", "Chamber", "Hall", "Cathedral", "Plate"}).def(2).group("Space");
    spaceDecay = b.add("space.decay").name("Decay").range(25, 300).log().def(100).unit("%").modulatable().group("Space");
    spaceSize = b.add("space.size").name("Size").range(50, 200).log().def(100).unit("%").modulatable().group("Space");
    spacePredelay = b.add("space.predelay").name("Pre-delay").range(0, 200).def(0).unit("ms").group("Space");
    spaceDamping = b.add("space.damping").name("Damping").range(0, 100).def(50).unit("%").modulatable().group("Space");
    spaceEarly = b.add("space.early").name("Early").range(-30, 6).def(0).unit("dB").group("Space");
    spaceLowCut = b.add("space.lowcut").name("Low Cut").range(20, 1000).log().def(50).unit("Hz").group("Space");
    spaceHighCut = b.add("space.highcut").name("High Cut").range(1000, 20000).log().def(16000).unit("Hz").modulatable().group("Space");
    resonance = b.add("string.resonance").name("Resonance").range(-40, 24).def(0).unit("dB").modulatable();
    bodySize = b.add("body.size").name("Body Size").range(50, 200).log().def(100).unit("%").modulatable();
    wolf = b.add("body.wolf").name("Wolf").range(0, 100).def(0).unit("%").modulatable();
    bowPos = b.add("bow.position").name("Bow Position").range(-100, 100).def(0).unit("%").modulatable();
    mute = b.add("body.mute").name("Mute").range(0, 100).def(0).unit("%").modulatable();
    wolfNote = b.add("body.wolfNote").name("Wolf Note").range(130, 260).log().def(175).unit("Hz");
    b.kitDefault("glide", 0.04);
  }
  void prepare(const PrepareInfo& info) override {
    glide = info.param("glide");
    voiceMode = info.param("voiceMode");
    reverb.prepare(static_cast<float>(info.sampleRate), kRoomWeightHz);
    a4 = info.param("sk.a4");
    symSr = static_cast<float>(info.sampleRate);
    symA4 = -1;
    for (int i = 0; i < kSympMax; ++i) symZr[i] = symZi[i] = 0;

  }

  // The open strings, tuned in pure fifths down from A3 (as cellists tune), at this A4: each one's
  // partials up to kSympFMax, their decay from the string's measured release (its octave band).
  void tuneSympathy(float a4Hz) {
    symN = 0;
    float f0 = 0.5f * a4Hz;                       // A3
    for (int st = kStrings - 1; st >= 0; --st, f0 *= 2.f / 3.f) {
      int lo; float tn;
      bracket(kOpen[st], lo, tn);
      for (int k = 1; k * f0 <= kSympFMax && symN < kSympMax; ++k) {
        const float f = k * f0;
        int b = static_cast<int>(std::lround(std::log2(f / cd::bandHz[0])));
        b = std::max(0, std::min(cd::kBands - 1, b));
        const float rate = cd::releaseDbS[lo][b] + tn * (cd::releaseDbS[lo + 1][b] - cd::releaseDbS[lo][b]);
        const float w = dsp::kTwoPi * f / symSr;
        const float r = std::pow(10.f, -rate / 20.f / symSr), rd = std::pow(10.f, -kSympDampDbS / 20.f / symSr);
        symPr[symN] = r * std::cos(w); symPi[symN] = r * std::sin(w);
        symDr[symN] = rd * std::cos(w); symDi[symN] = rd * std::sin(w);
        symRate[symN] = rate;
        symString[symN] = st;
        symK[symN] = k;
        ++symN;
      }
    }
    symA4 = a4Hz;
  }

  // The bank for one block: driven by the dry sound x (mono), adding its ring to io.
  void sympathy(GlobalContext& ctx, Buffer& io, int n) {
    const float a4Hz = ctx.get(a4);
    if (a4Hz != symA4) tuneSympathy(a4Hz);
    const float res = dsp::dbToGain(ctx.get(resonance));
    const float g = kSympK / symSr * res;

    float x[32], y[32] = {};
    for (int i = 0; i < n; ++i) x[i] = 0.5f * (io.left[i] + io.right[i]);
    for (int m = 0; m < symN; ++m) {
      const bool stopped = (stopMask >> symString[m]) & 1u;
      float zr = symZr[m], zi = symZi[m];
      if (stopped && zr * zr + zi * zi < 1e-20f) continue;   // stopped and silent: nothing to do
      const float pr = stopped ? symDr[m] : symPr[m], pi = stopped ? symDi[m] : symPi[m], gm = stopped ? 0.f : g;
      for (int i = 0; i < n; ++i) {
        const float r = zr * pr - zi * pi + gm * x[i];
        zi = zr * pi + zi * pr;
        zr = r;
        y[i] += zr;
      }
      symZr[m] = dsp::flushDenormal(zr);
      symZi[m] = dsp::flushDenormal(zi);
    }
    for (int i = 0; i < n; ++i) {
      io.left[i] += y[i];
      io.right[i] += y[i];
    }
  }
  // The room after the voices: the dry sound as it is (the voices are mono), the space's wet signal
  // added in stereo. At Reverb 0 the reverb stops once it has rung out and costs nothing.
  void processGlobal(GlobalContext& ctx, Buffer& io) override {
    const int n = std::min(io.frames, 32);
    sympathy(ctx, io, n);
    stopMask = 0;
    Ramp mix = ctx.ramp(room);
    bool on = false;
    for (int i = 0; i < n; ++i) {
      revIn[i] = 0.5f * (io.left[i] + io.right[i]);
      on = on || mix.at(i) > 0;
    }
    dsp::Reverb::Settings st{ctx.choice(spaceType), ctx.get(spaceDecay) * 0.01f, ctx.get(spaceSize) * 0.01f,
                             ctx.get(spaceDamping), ctx.get(spacePredelay), ctx.get(spaceEarly),
                             ctx.get(spaceLowCut), ctx.get(spaceHighCut), on};
    if (!reverb.process(st, revIn, revIn, wetL, wetR, n)) return;
    for (int i = 0; i < n; ++i) {
      const float k = mix.at(i) * 0.01f * kWet;
      io.left[i] += k * wetL[i];
      io.right[i] += k * wetR[i];
    }
  }
  void processEvents(EventContext& ctx) override {
    perString = ctx.choice(strings) == 1 && ctx.choice(voiceMode) == 0;
    // keyswitches move the Articulation choice (the page and the host follow) and don't sound; every
    // other note takes the articulation chosen when it arrives
    ++blocks;
    int cur = ctx.choice(articulation);
    const bool alternate = ctx.choice(bowing) == 1;
    for (auto& e : ctx.in()) {
      if (e.isNoteOn() || e.isNoteOff()) {
        const int ks = keyswitchArt(e.note);
        if (ks >= 0) {
          if (e.isNoteOn() && ks != cur) {
            cur = ks;
            ctx.setParam(articulation, static_cast<float>(ks));
          }
          continue;
        }
        const int key = e.note & 127;
        if (e.isNoteOn()) {
          noteArt[key] = cur;
          noteRR[key] = rrNext[key]++;   // each key its own round robins (each articulation takes its count)
          // a new bow turns it (once a block: a chord is one bow), unless the kit's legato slurs to it
          bool anyHeld = false;
          for (bool k : keyDown) anyHeld |= k;
          const bool slurs = ctx.choice(voiceMode) == 1 && anyHeld;
          if (alternate && !slurs && bowBlock != blocks) {
            bowUp = !bowUp;
            bowBlock = blocks;
          }
          noteUp[key] = alternate && bowUp;
          keyDown[key] = true;
        } else {
          keyDown[key] = false;
        }
      }
      ctx.out(e);
    }
  }
  // One note each: every string plays one note at a time, as on the cello. A note goes to the highest
  // string tuned below it that isn't playing a held note (re-bowing one that rings); if all of them
  // are, it takes the highest, as a slur (the left hand moves while the bow goes on).
  int allocateVoice(const NoteOn& n, VoicePool& pool) override {
    allocString = -1;
    if (!perString || pool.size() < kStrings) return pool.defaultAllocate(n);
    int top = stringFor(n.note), pick = -1;
    for (int c = top; c >= 0 && pick < 0; --c)
      if (pool.state(c) != VoicePool::State::Held) pick = c;
    if (pick < 0) pick = top;
    allocString = pick;
    return pick;
  }
  std::unique_ptr<Voice> makeVoice() override { return std::make_unique<StringsVoice>(*this); }

  // The wander filters' rms for unit noise at the reference speed (they're retuned with Speed; a
  // band-pass of fixed Q passes power in proportion to its centre, so the rms scales by its root),
  // and their steady states. Every voice has the same: worked out once per sample rate (in prepare,
  // which allocates nothing here either).
  struct WanderStats {
    float sr = 0;
    float normOct[cd::kOct], normFlick[kFlickBands];
    Stationary statOct[cd::kOct], statFlick[kFlickBands];
  } wander;
  const WanderStats& wanderStats(float sr) {
    if (wander.sr == sr) return wander;
    const float gr = sr / kGrid;
    for (int o = 0; o < cd::kOct; ++o) {
      BandPass f;
      f.set(cd::kLifeOct0 * std::pow(2.f, o + 0.5f), std::sqrt(2.f), gr);
      wander.normOct[o] = noiseRms(f);
      wander.statOct[o].of(f);
    }
    const float grf = gr / kFlickEvery;
    LowPass lp;
    lp.set(kFlickLpHz, grf);
    for (int j = 0; j < kFlickBands; ++j) {
      BandPass f;
      f.set(cd::kLifeOct0 * std::pow(4.f, j + 0.5f), 0.67f, grf);
      wander.normFlick[j] = noiseRms(f, &lp);   // through the band and the low-pass, as played
      wander.statFlick[j].of(f);
    }
    wander.sr = sr;
    return wander;
  }
};

void StringsVoice::prepare(const PrepareInfo& info) {
  sr = static_cast<float>(info.sampleRate);
  for (int b = 0; b < cd::kBands; ++b)
    for (auto& f : bp[b]) f.set(cd::bandHz[b], cd::kNoiseQ, sr);
  // the wander filters' rms for unit noise at the reference speed, and their steady states: the same
  // for every voice, so worked out once per sample rate (the synth keeps them) and copied
  const auto& w = synth.wanderStats(sr);
  for (int o = 0; o < cd::kOct; ++o) { normOct[o] = w.normOct[o]; statOct[o] = w.statOct[o]; }
  for (int j = 0; j < kFlickBands; ++j) { normFlick[j] = w.normFlick[j]; statFlick[j] = w.statFlick[j]; }
  const float gr = sr / kGrid;
  // vibrato's irregularity: a one-pole on unit-variance draws, scaled to unit rms
  vibA = 1.f - std::exp(-dsp::kTwoPi * kVibVaryHz / gr);
  vibNormVary = 1.f / std::sqrt(vibA / (2.f - vibA));
  glideRate = 1.f / (kGlideS * sr);
  followRate = 1.f / (kFollowS * sr);
}

void StringsVoice::tuneHarm(int k, float speed) {
  const float grf = sr / kGrid / kFlickEvery;
  for (int j = 0; j < kFlickBands; ++j) wHarm[k][j].set(cd::kLifeOct0 * std::pow(4.f, j + 0.5f) * speed, 0.67f, grf);
  wHarmLp[k].set(kFlickLpHz * speed, grf);
}

void StringsVoice::tuneWander(float speed) {
  const float gr = sr / kGrid;
  for (int o = 0; o < cd::kOct; ++o) {
    float fc = cd::kLifeOct0 * std::pow(2.f, o + 0.5f) * speed;
    wPitch[o].set(fc, std::sqrt(2.f), gr);
    wLevel[o].set(fc, std::sqrt(2.f), gr);
    for (int c = 0; c < cd::kPat; ++c) wPat[c][o].set(fc, std::sqrt(2.f), gr);
  }
  wLevelLp.set(kLevelLpHz * speed, gr);
  for (int c = 0; c < cd::kPat; ++c) wPatLp[c].set(kFlickLpHz * speed, gr);
  for (int k = 0; k < K; ++k) tuneHarm(k, speed);
  wSpeed = speed;
}

// A new key, a slur, or a string bowed again. The kit's legato (Legato mode) and a key taking a held
// string (One Note Each) are slurs: the bow goes on and only the pitch moves. A voice that still
// sounds otherwise (Mono, a re-bowed string, a taken voice) fades what it played, then starts.
void StringsVoice::start(const NoteOn& n, const StartInfo& s) {
  auto& r = rng();
  const int str = synth.allocString;
  const bool held = alive && !releasing && !restart;
  const int a = synth.noteArt[n.note & 127], rr = synth.noteRR[n.note & 127];
  const bool up = synth.noteUp[n.note & 127];
  // a pizzicato is plucked again whatever the voice mode (a bowed note slurs only into a bowed note)
  const bool slur = (a == kArco || a == kTrem) && (!alive || art == a);
  if (slur && (s.legato || (s.sounding && str >= 0 && held))) {
    velDyn = dynOf(n.vel);
    slurArt = true;           // the finger moves: the tone dips and the vibrato starts again
    if (!s.legato) {          // the kit glides only in its own legato: a string slur glides here
      slurFrom = midiNow;
      slurPending = true;
    }
    if (str >= 0) assigned = str;
    return;
  }
  uint64_t seeds[3];
  for (auto& v : seeds) v = static_cast<uint64_t>(r.integer(1, 1 << 30));
  assigned = str;
  if ((s.sounding || s.legato) && alive && !pending) {
    restart = true;
    fadeLen = fadeLeft = std::max(1, static_cast<int>(kRebowS * sr));
    nextVel = n.vel;
    nextArt = a;
    nextRR = rr;
    nextUpBow = up;
    nextTremSeed = synth.blocks;
    for (int j = 0; j < 3; ++j) nextSeeds[j] = seeds[j];
    releasing = false;
    return;
  }
  vel = n.vel;
  art = a;
  rrSel = rr;
  upBow = up;
  tremSeed = synth.blocks;
  seedNoise = seeds[0]; seedWander = seeds[1]; seedVib = seeds[2];
  pending = true;
  alive = true;
  releasing = released = false;
  bankOn = false;
  restart = false;
  t = 0;
}

void StringsVoice::setRotation(float hz) {
  float w = dsp::kTwoPi * hz / sr;
  float c1 = std::cos(w), s1 = std::sin(w), c = 1, s = 0;
  for (int k = 0; k < K; ++k) {
    float nc = c * c1 - s * s1, ns = c * s1 + s * c1;
    c = nc; s = ns;
    rc[k] = c; rs[k] = s;
  }
}

// The dynamic the sustain plays at: the key's velocity, or the Dynamics control (CC 1 and 11) moving
// through the note (the velocity then sets only the onset: how hard the bow catches).
float StringsVoice::sustainDyn() const { return pDynCtl ? pDyn : velDyn; }

// Bow Position's change to the source at harmonic n (dB): the bowing point's nodes and the tilt past
// what the dynamics give.
float StringsVoice::posDb(int n) const {
  if (pPos == 0) return 0;
  const float a = std::fabs(pPos);
  const float beta = kPosBeta0 * std::pow(pPos > 0 ? kPosBridge : kPosTasto, -pPos);
  const float sn = std::sin(dsp::kPi * n * beta);
  const float node = 10.f * std::log10(kPosNodeFloor * kPosNodeFloor + (1 - kPosNodeFloor * kPosNodeFloor) * sn * sn);
  const float l = std::log2(static_cast<float>(n));
  float tilt = pPos > 0 ? pPos * (6.f * std::max(0.f, l - 2.f) - (n == 1 ? 6.f : 0.f))
                        : pPos * 5.f * std::max(0.f, l - 1.585f);   // −5 dB per octave above the 3rd
  return std::max(-30.f, a * node + tilt);
}

// The mute's change at frequency f (dB): a dip over the bridge's resonance region, a gentler cut above
// it, and (past 50 %) the lows and the level with it.
float StringsVoice::muteDb(float f) const {
  const float x = std::log2(f / kMuteHillHz) / kMuteHillOct;
  const float hill = std::exp(-0.5f * x * x);
  const float u = dsp::clamp(std::log2(f / 600.f) / std::log2(2500.f / 600.f), 0.f, 1.f);
  const float high = u * u * (3 - 2 * u);
  const float heavy = std::max(0.f, 2.f * pMute - 1.f);
  return -pMute * (kMuteHillDb * hill + kMuteHighDb * high) - kMuteHeavyDb * heavy;
}

// A note's steady level: as its measured neighbours were recorded, or (Even Notes) from a smooth curve
// along the keyboard, as a player keeps a line even. Each note keeps its own timbre either way.
float StringsVoice::levelAt(int l, float t, float d) const {
  float rec = cellLerp(l, t, d, [](int a, int b) { return cd::level[a][b]; });
  float even = cellLerp(l, t, d, [](int a, int b) { return cd::levelEven[a][b]; });
  return rec + pEven * (even - rec);
}

// Everything that depends on where the pitch is among the measured notes and on the dynamic: the level,
// the source, the corrections' weights, the release, the movement's size, the noise. Called as the
// pitch moves (a slur, a bend, a glide) or the dynamic does.
void StringsVoice::place(float hz) {
  const double midi = 69.0 + 12.0 * std::log2(hz / 440.0);
  bracket(midi, lo, tn);
  // the source and the measured notes' corrections at the bow's weight; the level and the noise at
  // the dynamic
  const float tDyn = dsp::clamp(dyn + kWeightLayers * pWeight, -0.5f, cd::kDyns - 0.5f);
  d0 = dsp::clamp(static_cast<int>(std::floor(tDyn)), 0, cd::kDyns - 2);
  td = tDyn - d0;
  level = levelAt(lo, tn, dyn);
  int k1 = std::max(1, std::min(kMaxHarm, static_cast<int>(cd::kFMax / hz)));
  if (k1 > K) extend(k1);
  wLo = std::max(0.f, 1.f - static_cast<float>(midi - cd::noteMidi[lo]) / kCorrSpan);
  wHi = std::max(0.f, 1.f - static_cast<float>(cd::noteMidi[lo + 1] - midi) / kCorrSpan);
  // Bow Position moves the source alone along the dynamics (not the measured notes' corrections,
  // which carry each take's own quirks: C3's mp take has a weak fundamental)
  const float pDynT = dsp::clamp(tDyn + kPosLayers * pPos, -0.5f, cd::kDyns - 0.5f);
  const int p0 = dsp::clamp(static_cast<int>(std::floor(pDynT)), 0, cd::kDyns - 2);
  const float pt = pDynT - p0;
  if (hNode > 1) {
    // a harmonic: the touched string's harmonics n, 2n, 3n, ... less what the finger takes; the
    // measured notes' corrections belong to stopped notes
    for (int k = 0; k < K; ++k) {
      const int j = hNode * (k + 1);
      const float sj = j <= cd::kHarm ? cd::source[p0][j - 1] + pt * (cd::source[p0 + 1][j - 1] - cd::source[p0][j - 1]) : -120.f;
      srcDb[k] = sj + posDb(j) + touch_data::takeDb[std::min(k, touch_data::kM - 1)];
    }
    wLo = wHi = 0;
    level += touch_data::kLevelDb;
  } else {
    for (int k = 0; k < K; ++k) srcDb[k] = cd::source[p0][k] + pt * (cd::source[p0 + 1][k] - cd::source[p0][k]) + posDb(k + 1);
  }
  // the release: each harmonic's band's decay after the bow stops
  const float l2b = std::log2(hz / cd::bandHz[0]);
  for (int k = 0; k < K; ++k) {
    int b = static_cast<int>(std::lround(l2b + kLog2K.v[k]));
    b = std::max(0, std::min(cd::kBands - 1, b));
    float rr = cd::releaseDbS[lo][b] + tn * (cd::releaseDbS[lo + 1][b] - cd::releaseDbS[lo][b]);
    relRate[k] = -rr / sr * kLn10_20;   // dB/s → ln gain per sample
  }
  for (int o = 0; o < cd::kOct; ++o) {
    rmsPitch[o] = cd::lifePitch[lo][o] + tn * (cd::lifePitch[lo + 1][o] - cd::lifePitch[lo][o]);
    rmsLevel[o] = o < kLevelOcts ? cd::lifeLevel[lo][o] + tn * (cd::lifeLevel[lo + 1][o] - cd::lifeLevel[lo][o]) : 0.f;
  }
  // bow noise, as measured, for unit-variance noise at the data's rate
  float moved = 0;
  for (int b = 0; b < cd::kBands; ++b) {
    float g = cellLerp(lo, tn, dyn, [b](int a, int c) { return cd::noiseDb[a][c][b]; });
    // noiseDb: the band's power re the harmonic rms (level), in dB; for noise at sr rather than the
    // data's rate the same filter passes kOnsetRate / sr as much power
    noiseGain[b] = dsp::dbToGain(g + level) * std::sqrt(sr / cd::kOnsetRate);
    float gd = cellLerp(lo, tn, dyn, [b](int a, int c) { return cd::grainDepth[a][c][b]; });
    moved = std::max(moved, std::fabs(gd - grainDepth[b]));
    grainDepth[b] = gd;
  }
  if (moved > 0.01f) grainAmount = -1;   // the pulse's tables follow
  placeHz = hz;
  placeDyn = dyn;
  placeWeight = pWeight;
  placePos = pPos;
  placeEven = pEven;
}

// Harmonics added as the pitch falls (a slur or glide down): silent, in their steady state, rising
// to their targets with the rest.
void StringsVoice::extend(int k1) {
  for (int k = K; k < k1; ++k) {
    amp[k] = 0;
    target[k] = 0;
    zr[k] = 1e-12f;
    zi[k] = 0;
    rc[k] = 1;      // still, until the step sets its rotation (never another note's left over)
    rs[k] = 0;
    gain[k] = 1;
    flick[k] = 1;
    hand[k] = 0;
    handPh[k] = 0;
    tuneHarm(k, wSpeed > 0 ? wSpeed : 1.f);
    for (int j = 0; j < kFlickBands; ++j) statFlick[j].draw(wHarm[k][j], wrng);
    wHarmLp[k].reset();
  }
  K = k1;
}

// The steady spectrum at a pitch: the source (by harmonic number) plus the parts that belong to
// frequency, the body and the measured notes' corrections, scaled by Body; normalised to the level.
// The body's fine detail is read every step and moves energy between the harmonics (below), so it
// leaves the level as it is. Harmonics above kFMax go silent (a slur or glide up).
void StringsVoice::spectrum(float hz) {
  float sum = 0;
  const float l2 = std::log2(hz), l2b = l2 + std::log2(pSize);
  for (int k = 0; k < K; ++k) {
    float f = (k + 1) * hz;
    if (f > cd::kFMax) { target[k] = 0; continue; }
    const float fb = f * pSize;   // where on the body this harmonic falls (Body Size)
    float fd = bodyDbLog2(l2b + kLog2K.v[k]);
    if (wLo > 0) fd += wLo * (corrDb(lo, d0, fb) + td * (corrDb(lo, d0 + 1, fb) - corrDb(lo, d0, fb)));
    if (wHi > 0) fd += wHi * (corrDb(lo + 1, d0, fb) + td * (corrDb(lo + 1, d0 + 1, fb) - corrDb(lo + 1, d0, fb)));
    target[k] = fastExp(kLn10_20 * (srcDb[k] + pBody * fd));
    sum += target[k] * target[k];
  }
  float norm = std::sqrt(2.f) * dsp::dbToGain(level) / std::sqrt(std::max(sum, 1e-30f));
  for (int k = 0; k < K; ++k) target[k] *= norm;
  // the mute: after the level, so it's quieter
  if (pMute > 0)
    for (int k = 0; k < K; ++k) target[k] *= fastExp(kLn10_20 * muteDb((k + 1) * hz));
  specHz = hz;
  specBody = pBody;
  specSize = pSize;
  specMute = pMute;
}

// The noise pulse per band: u^p, u = (1 + cos(θ - ψ)) / 2, with p for the measured depth times
// Grain, normalised to unit mean power so the band's level stays as measured.
void StringsVoice::grainShape(float amount) {
  for (int b = 0; b < cd::kBands; ++b) {
    float d = dsp::clamp(grainDepth[b] * amount, 0.f, 1.9f) / 0.05f;
    int i = std::min(static_cast<int>(d), cd::kGrainSteps - 2);
    float p = cd::grainExp[i] + (d - i) * (cd::grainExp[i + 1] - cd::grainExp[i]);
    double pw = 0;
    for (int j = 0; j < kGrainTable; ++j) {
      float th = dsp::kTwoPi * j / kGrainTable;
      float u = 0.5f + 0.5f * std::cos(th - grainPh[b]);
      grain[b][j] = p > 0 ? std::pow(std::max(u, 1e-9f), p) : 1.f;
      pw += double(grain[b][j]) * grain[b][j];
    }
    float norm = static_cast<float>(1.0 / std::sqrt(pw / kGrainTable));
    for (int j = 0; j < kGrainTable; ++j) grain[b][j] *= norm;
    grain[b][kGrainTable] = grain[b][0];
  }
  grainAmount = amount;
}

// Everything a new note starts from, read at its first render (parameters and the pitch are
// available there: API.md §4).
void StringsVoice::setup(VoiceContext& ctx) {
  rng_.seed(seedNoise);
  wrng.seed(seedWander);
  vrng.seed(seedVib);
  const double midi = ctx.pitch();
  const float hz = static_cast<float>(ctx.pitchHz());
  midiNow = midi;
  velDyn = dynOf(vel);
  dyn = sustainDyn();
  K = 0;
  wSpeed = pSpeed;
  for (auto& g : grainDepth) g = 0;
  hNode = art == kHarmonic ? harmonicNode(midi) : 1;
  place(hz);

  // the onset: the nearest measured note's, at the velocity's nearest dynamic, transposed to this pitch
  int on = tn < 0.5f ? lo : lo + 1;
  if (midi <= cd::noteMidi[0]) on = 0;
  if (midi >= cd::noteMidi[cd::kNotes - 1]) on = cd::kNotes - 1;
  const int vd = std::min(cd::kDyns - 1, static_cast<int>(velDyn + 0.5f));
  int od = cd::onsetDyn[on][vd];
  // an up-bow (Bowing: Alternate) starts from the cell's up-bow take, where it has a steady one
  // (tools/upbow.py); its sustain is the cell's own, as the down-bow's is
  const int ut = upBow && art == kArco ? upbow_data::take[on][vd] : -1;
  onset = ut >= 0 ? upbow_data::onset[ut] : cd::onset[on * cd::kDyns + od];
  onsetLen = cd::kOnsetLen;
  bowOff = -1;
  strokeFade = 0;
  float ratio = hz / (ut >= 0 ? upbow_data::handF0[ut] : cd::handF0[on][od]);
  stepBase = step_ = ratio * cd::kOnsetRate / sr;
  hzOnset = hz;
  pos = 0;
  // the onset plays at the velocity's level (the sustain may be at another: Dynamics From Controller)
  float onsetLevel = levelAt(lo, tn, velDyn);
  float cellDb = onsetLevel - (ut >= 0 ? upbow_data::level[ut] : cd::level[on][od]);
  onsetGain = dsp::dbToGain(cellDb) * (ut >= 0 ? upbow_data::kOnsetScale : cd::kOnsetScale);
  onsetRel = 1;
  onsetRelMul = dsp::dbToGain(-kOnsetReleaseDbS / sr);
  tX0 = static_cast<long>(cd::kTOn * cd::kOnsetRate / step_);
  tX1 = static_cast<long>((cd::kTOn + cd::kXf) * cd::kOnsetRate / step_);
  tC = static_cast<long>(cd::kTC * cd::kOnsetRate / step_);

  pBody = ctx.get(synth.body) * 0.01f;
  spectrum(hz);

  // the onset's harmonics at the hand-off, which the bank starts from
  float hg = dsp::dbToGain(cellDb);
  for (int k = 0; k < K; ++k) {
    if (ut >= 0) {
      hand[k] = k < upbow_data::handCount[ut] ? hg * dsp::dbToGain(0.01f * upbow_data::handDb[ut][k]) : 0.f;
      handPh[k] = upbow_data::handPh[ut][k] * (dsp::kPi / 128.f);
    } else {
      hand[k] = k < cd::handCount[on][od] ? hg * dsp::dbToGain(0.01f * cd::handDb[on][od][k]) : 0.f;
      handPh[k] = cd::handPh[on][od][k] * (dsp::kPi / 128.f);
    }
    gain[k] = 1;
    flick[k] = 1;
  }
  if (isStroke(art)) setupStroke(midi, hz, on, od);
  if (hNode > 1) {
    // no recording starts a harmonic: the bank, at its steady spectrum, swells in
    onset = nullptr;
    tX0 = tC = 0;
    tX1 = std::max(1L, static_cast<long>(kHarmAttackS * sr));
    for (int k = 0; k < K; ++k) {
      hand[k] = target[k];
      handPh[k] = 0;
    }
  }

  // the harmonics' own movement: the onset's cell's patterns (the same recording), and its leftover
  // part's spectrum split into the three two-octave bands (up to 16 Hz: the rest is closed off)
  const int cell = on * cd::kDyns + od;
  for (int c = 0; c < cd::kPat; ++c) {
    shape[c] = cd::lifeShape[cell][c];
    // up to 16 Hz only, as a harmonic's leftover movement: faster, its sidebands land between the
    // harmonics as noise (on C3 they put 14-25 dB more there than the recording has)
    for (int o = 0; o < cd::kOct; ++o) rmsPat[c][o] = o < 6 ? cd::lifeShapeOct[cell][c][o] : 0.f;
    wPatLp[c].reset();
    score[c] = 0;
  }
  residK = cd::lifeResidK[cell];
  for (int j = 0; j < kFlickBands; ++j) {
    float a = 0;
    for (int o = 2 * j; o < 2 * j + 2; ++o) a += cd::lifeResidOct[cell][o] * cd::lifeResidOct[cell][o];
    rmsHarm[j] = std::sqrt(a);
  }
  // the wander starts in its steady state (drawn at Speed 100 %'s statistics: near enough at others)
  tuneWander(pSpeed);
  wLevelLp.reset();
  for (int o = 0; o < cd::kOct; ++o) {
    statOct[o].draw(wPitch[o], wrng);
    statOct[o].draw(wLevel[o], wrng);
    for (int c = 0; c < cd::kPat; ++c) statOct[o].draw(wPat[c][o], wrng);
  }
  for (int k = 0; k < K; ++k) {
    for (int j = 0; j < kFlickBands; ++j) statFlick[j].draw(wHarm[k][j], wrng);
    wHarmLp[k].reset();
  }
  pitchC = levelDb = 0;

  for (int b = 0; b < cd::kBands; ++b) {
    // the noise's pulse peaks where the down-bow's does; an up-bow's half a period away (the bow
    // reversed mirrors the string's motion: measured 171 degrees apart, median)
    grainPh[b] = cd::grainPhase[on][od][b] + (ut >= 0 ? dsp::kPi : 0.f);
    for (auto& f : bp[b]) f.reset();
  }
  grainAmount = -1;
  noiseDrive = 0;
  noiseRelMul = std::exp(-1.f / (kNoiseReleaseS * sr));

  // vibrato starts afresh with each bow
  string = curString = assigned >= 0 ? assigned : stringFor(midi);
  vibPh = 0;
  vibR = vibD = 0;
  vibDepth = 0;
  vibT0 = 0;
  vibSlurred = vibRephase = false;
  artT0 = -1;
  artGain = artPrev = 1;
  slurArt = false;
  vibScale = std::exp2((dsp::clamp(static_cast<float>(midi) - kOpen[string], 0.f, 30.f) - kVibRefSemis) / 12.f);
  slurC = slurRate = 0;
  slurPending = false;
  setRotation(hz);
  fNow = hz;
  if (art == kTrem) setupTrem();
}

// A tremolo starts with its first stroke; the model only rings it down once it's let go.
void StringsVoice::setupTrem() {
  trng.seed(0x7e3017u + tremSeed * 2654435761u);
  crng.seed(seedVib ^ 0x5bd1e995u);
  onset = nullptr;
  bowOff = -1;
  tX0 = tC = kNever;
  tX1 = kNever + 1;
  onsetRel = 1;
  for (auto& g : tg) g = TremGrain{};
  tgCur = 0;
  tremDir = 1;
  tremLast[0] = tremLast[1] = -1;
  tremNext = 0;
  tremXfT0 = 0;
  tremXfLen = tremXfNext = 1;
  tremDrift = 0;
  tremJ = kTremJitter * kUnitSd * trng.bipolar();
  tremAlt = trng.chance(0.5f) ? 1.f : -1.f;
  tremEven = false;
  tremStop = false;
  tremDb = level;
}

// A new stroke at note sample ti: a take bowed this way, lined up with the stroke it follows, and how
// long it lasts.
void StringsVoice::tremStroke(long ti) {
  const TremGrain& old = tg[tgCur];
  const bool first = old.x == nullptr;
  int on = tn < 0.5f ? lo : lo + 1;
  if (midiNow <= cd::noteMidi[0]) on = 0;
  if (midiNow >= cd::noteMidi[cd::kNotes - 1]) on = cd::kNotes - 1;
  const int d = dsp::clamp(static_cast<int>(std::lround(dyn + kTremDynSpread * crng.bipolar())), 0, sd::kDyns - 1);
  const int cell = on * sd::kDyns + d, n = sd::tremCount[cell];
  // a take bowed this way, not the one this bow played last; else any bowed this way; else any, turned over
  int cand[sd::kTremPer], c = 0;
  const int side = tremDir > 0 ? 1 : 0;
  for (int pass = 0; pass < 3 && c == 0; ++pass)
    for (int j = 0; j < n; ++j)
      if ((pass == 2 || sd::tremDir[cell][j] == tremDir) && (pass > 0 || cell * sd::kTremPer + j != tremLast[side])) cand[c++] = j;
  const int j = cand[c > 1 ? crng.integer(0, c - 1) : 0];
  tremLast[side] = cell * sd::kTremPer + j;
  const float sign = sd::tremDir[cell][j] == tremDir ? 1.f : -1.f;
  const int src = sd::tremSrc[cell][j];
  TremGrain& g = tg[tgCur ^ 1];
  g.x = src >= 0 ? sd::onset[src] + sd::tremStart[cell][j] : sd::tremGrain[-1 - src];
  g.len = sd::tremAvail[cell][j];
  g.f0 = sd::tremF0[cell][j];
  g.ph0 = sd::tremPh[cell][j] + (sign < 0 ? dsp::kPi : 0.f);
  g.stepK = static_cast<float>(sd::kOnsetRate) / (sr * g.f0);
  // its level: a held note's for the dynamic (with Even Notes), and its own
  tremDb = level + kTremTrimDb + kTremLevelDb * kUnitSd * crng.bipolar();
  g.g = sign * dsp::dbToGain(tremDb - sd::tremRef[cell][j]) * sd::kOnsetScale;
  if (first) {
    g.pos = 0;
    tremXfLen = std::max(1, static_cast<int>(0.001f * sr));
  } else {
    // the bow turned: the string's motion turns over, so the new stroke's fundamental starts half a
    // cycle from where the old one's is
    const float phOld = old.ph0 + dsp::kTwoPi * old.f0 * static_cast<float>(old.pos / sd::kOnsetRate);
    float dph = std::fmod(phOld + dsp::kPi - g.ph0, dsp::kTwoPi);
    if (dph < 0) dph += dsp::kTwoPi;
    g.pos = dph / dsp::kTwoPi * sd::kOnsetRate / g.f0;
    tremXfLen = tremXfNext;
  }
  tgCur ^= 1;
  tremXfT0 = ti;
  // how long it lasts: the beat drifting, the change jittered (a long stroke, then a short), one bow longer
  tremDrift = kTremDriftPole * tremDrift + kTremDrift * kUnitSd * trng.bipolar();
  const float jn = kTremJitter * kUnitSd * trng.bipolar();
  const float r = tremDrift + tremAlt * (tremEven ? -kTremAlt : kTremAlt) + (jn - tremJ) + kTremWobble * kUnitSd * trng.bipolar();
  tremJ = jn;
  tremEven = !tremEven;
  const float len = sr / pTremRate * dsp::clamp(1 + r, kTremMinLen, kTremMaxLen);
  tremXfNext = std::max(1, static_cast<int>(trng.uniform(kTremXfMinS, kTremXfMaxS) * sr));
  // never past what the take holds (with its change, and room for the pitch to rise)
  const float room = (g.len - 3 - static_cast<float>(g.pos)) / std::max(fNow * g.stepK, 1e-6f) - tremXfNext - 2 * kGrid;
  tremNext = ti + std::max(1L, static_cast<long>(std::min(len, std::max(room, static_cast<float>(kGrid)))));
  tremDir = -tremDir;
}

// Letting go: the stroke under way ends, and the model's release rings on from its level.
void StringsVoice::tremEnd() {
  tremStop = true;
  tX0 = tC = std::max(t + 1, tremNext);
  tX1 = tX0 + std::max(1L, static_cast<long>(kTremEndXfS * sr));
  const float g = dsp::dbToGain(tremDb - level);
  for (int k = 0; k < K; ++k) hand[k] = target[k] * g;
}

// This sample of the strokes: the one under way fading in at its change, the last one fading out.
float StringsVoice::tremSample(long ti) {
  float y = 0;
  const float u = static_cast<float>(ti - tremXfT0 + 1) / tremXfLen;
  for (int r = 0; r < 2; ++r) {
    TremGrain& g = tg[r];
    if (!g.x) continue;
    const float w = r == tgCur ? std::min(1.f, u) : 1.f - u;
    if (w <= 0) {
      g.x = nullptr;
      continue;
    }
    const int ip = static_cast<int>(g.pos);
    if (ip + 2 < g.len) {
      const float fr = static_cast<float>(g.pos - ip);
      const float xm = ip > 0 ? g.x[ip - 1] : 0.f, x0 = g.x[ip], x1 = g.x[ip + 1], x2 = g.x[ip + 2];
      const float c1 = 0.5f * (x1 - xm), c2 = xm - 2.5f * x0 + 2 * x1 - 0.5f * x2, c3 = 0.5f * (x2 - xm) + 1.5f * (x0 - x1);
      y += w * g.g * (((c3 * fr + c2) * fr + c1) * fr + x0);
    }
    g.pos += static_cast<double>(fNow) * g.stepK;
  }
  return y;
}

// A staccato or spiccato (docs/MODEL.md: Strokes): the bowed note's setup, then its own take (the
// nearest measured note's, at the velocity's nearest dynamic, a round robin of two): the take's onset,
// transposed to this pitch; its harmonics where the recording hands over; and where its bow leaves.
// A staccato's recording hands over at its bow-off or at 0.25 s, the model playing the rest of a longer
// stroke; a spiccato's leaves at the bounce (a judgment), from the take one dynamic lighter.
void StringsVoice::setupStroke(double midi, float hz, int on, int od) {
  const bool sp = art == kSpicc;
  const int d = sp ? std::max(0, od - 1) : od;
  const int take = (on * sd::kDyns + d) * sd::kKeep + rrSel % sd::kKeep;
  onset = sd::onset[take];
  onsetLen = sd::kOnsetLen;
  const float ratio = hz / (sp ? sd::spF0[take] : sd::handF0[take]);
  stepBase = step_ = ratio * sd::kOnsetRate / sr;
  // the stroke's level: the staccatos' at this velocity (its own Even Notes curve); a spiccato's at the
  // bounce kSpiccDb under it
  const float rec = cellLerp(lo, tn, velDyn, [](int a, int b) { return sd::level[a][b]; });
  const float even = cellLerp(lo, tn, velDyn, [](int a, int b) { return sd::levelEven[a][b]; });
  const float want = rec + pEven * (even - rec) - (sp ? kSpiccDb : 0.f);
  const float cellDb = want - (sp ? sd::spLevel[take] : sd::takeLevel[take]);
  onsetGain = dsp::dbToGain(cellDb) * sd::kOnsetScale;
  const float toNote = sd::kOnsetRate / step_;   // recording seconds to note samples
  const float t0 = sp ? sd::tSp[take] : sd::tHand[take];
  const float xf = sp ? sd::kSpXf : sd::kXf;
  tX0 = static_cast<long>(t0 * toNote);
  tX1 = static_cast<long>((t0 + xf) * toNote);
  tC = static_cast<long>((t0 + 0.5f * xf) * toNote);
  bowOff = sp ? tX0 : std::max(tX0, static_cast<long>(sd::tOff[take] * toNote));
  strokeFade = std::min(0.f, sd::fadeDbS[take]) / sr * kLn10_20;
  const float hg = dsp::dbToGain(cellDb);
  const int n = sp ? sd::spCount[take] : sd::handCount[take];
  for (int k = 0; k < K; ++k) {
    hand[k] = k < n ? hg * dsp::dbToGain(0.01f * (sp ? sd::spDb[take][k] : sd::handDb[take][k])) : 0.f;
    handPh[k] = (sp ? sd::spPh[take][k] : sd::handPh[take][k]) * (dsp::kPi / 128.f);
    // the take's own release: each harmonic as it decayed after the bow left
    strokeRel[k] = -0.1f * sd::relDbS[take][std::min(k, sd::kHarm - 1)] / sr * kLn10_20;
  }
  (void)midi;
}

// Sum of octave-band noises (one white draw each), each scaled to its measured rms.
float StringsVoice::wanderOctaves(BandPass* f, const float* rms, float scale) {
  float y = 0;
  for (int o = 0; o < cd::kOct; ++o) {
    if (rms[o] < 1e-4f) continue;
    y += f[o].process(wrng.bipolar() * 1.7320508f) * rms[o] / normOct[o];
  }
  return y * scale;
}

// One kGrid step of the voice's own time: the bow's movement, vibrato, the spectrum following the
// pitch and the dynamic, the glide and the release. Done on the voice's clock, never per render
// call, so the result doesn't depend on the block size.
void StringsVoice::step(VoiceContext& ctx) {
  const float hz = static_cast<float>(ctx.pitchHz());
  const double midi = ctx.pitch();

  // a slur within a string (One Note Each): from the old pitch to the new over the glide time
  if (slurPending) {
    slurC = static_cast<float>((slurFrom - midi) * 100.0);
    slurRate = pGlide > 0.0005f ? std::fabs(slurC) / (pGlide * sr) * kGrid : 1e9f;
    slurPending = false;
  }
  if (slurC != 0) slurC = slurC > 0 ? std::max(0.f, slurC - slurRate) : std::min(0.f, slurC + slurRate);
  curString = assigned >= 0 ? assigned : stringFor(midi);
  if (slurArt) {
    slurArt = false;
    vibT0 = t;
    vibSlurred = vibRephase = true;
    artT0 = pSlur > 0 ? t : -1;
  }
  // the articulation's dip (raised-cosine ramps)
  artPrev = artGain;
  artGain = 1;
  if (artT0 >= 0) {
    const float u = static_cast<float>(t - artT0) / sr;
    const float hold = kSlurHoldS * pSlur, rise = kSlurRiseS * (0.5f + 0.5f * pSlur);
    float w;
    if (u < kSlurFallS) w = 0.5f - 0.5f * std::cos(dsp::kPi * u / kSlurFallS);
    else if (u < kSlurFallS + hold) w = 1;
    else if (u < kSlurFallS + hold + rise) w = 0.5f + 0.5f * std::cos(dsp::kPi * (u - kSlurFallS - hold) / rise);
    else { w = 0; artT0 = -1; }
    artGain = std::exp2(-kSlurDb * pSlur * w * (1.f / 6.0206f));
  }
  // the wolf: near its note the tone stutters
  if (pWolf > 0 && bankOn && !released) {
    const float c = 1200.f * std::log2(static_cast<float>(ctx.pitchHz()) / pWolfHz);
    const float w = std::exp(-(c * c) / (kWolfWidthC * kWolfWidthC));
    if (w > 1e-3f) {
      wolfR += vibA * (vrng.bipolar() * 1.7320508f - wolfR);
      wolfPh += dsp::kTwoPi * kWolfHz * (0.6f + 0.4f * w) * (1.f + 0.15f * wolfR * vibNormVary) * kGrid / sr;
      if (wolfPh > dsp::kTwoPi) wolfPh -= dsp::kTwoPi;
      const float u = 0.5f - 0.5f * std::cos(wolfPh);   // 0 … 1, the dip at its middle
      artGain *= std::exp2(-kWolfDb * pWolf * w * u * u * (1.f / 6.0206f));
    }
  }
  midiNow = midi + slurC * 0.01;

  // the life comes in once the hand-off is over (during it the model must match the recording);
  // it stops moving when the bow leaves
  float lifeW = dsp::clamp((t - tX1) / (kLifeInS * sr), 0.f, 1.f) * pLife;
  if (!released && bankOn) {
    if (pSpeed != wSpeed) tuneWander(pSpeed);
    const float sp = 1.f / std::sqrt(pSpeed);   // a filter's rms for unit noise grows with its centre
    pitchC = wanderOctaves(wPitch, rmsPitch, sp * lifeW * pPitch);
    levelDb = dsp::clamp(wLevelLp.process(wanderOctaves(wLevel, rmsLevel, sp * lifeW)), -12.f, 12.f);
    // each harmonic's own movement is measured against the note's level, so it moves energy between
    // the harmonics and leaves the level to the level's own wander: c takes out what it would add
    float fl = sp * lifeW * pFlicker;
    for (int c = 0; c < cd::kPat; ++c) score[c] = wPatLp[c].process(wanderOctaves(wPat[c], rmsPat[c], 1.f));
    const bool flickNow = (t / kGrid) % kFlickEvery == 0;
    float num = 0, den = 0;
    for (int k = 0; k < K; ++k) {
      if (!flickNow) {   // between updates each harmonic keeps its own movement; the sums still follow amp
        float a2 = amp[k] * amp[k];
        num += a2 * flick[k] * flick[k];
        den += a2;
        continue;
      }
      float h = 0;
      // unit-variance uniform draws: the narrow filters make their output Gaussian enough, and a
      // normal draw costs a log, a cos and a square root
      for (int j = 0; j < kFlickBands; ++j) h += wHarm[k][j].process(wrng.bipolar() * 1.7320508f) * rmsHarm[j] / normFlick[j];
      h = wHarmLp[k].process(h) * residK[std::min(k, kMaxHarm - 1)];
      if (k < cd::kPatHarm)
        for (int c = 0; c < cd::kPat; ++c) h += shape[c][k] * score[c];
      // a harmonic can sink far but rise only so much: Life and Flicker multiply, and at their tops a
      // high harmonic's own movement would otherwise swing by tens of dB
      flick[k] = fastExp(kLn10_20 * dsp::clamp(fl * h, -40.f, 12.f));   // as a gain
      float a2 = amp[k] * amp[k];
      num += a2 * flick[k] * flick[k];
      den += a2;
    }
    const float lg = fastExp(kLn10_20 * levelDb) * (num > 0 ? std::sqrt(den / num) : 1.f);
    for (int k = 0; k < K; ++k) gain[k] = lg * flick[k];
  }

  const float vibC = vibratoC(midi);
  const float f = hz * std::exp2((pitchC + vibC + slurC) * (1.f / 1200.f));
  // the onset recording follows the pitch too (a bend, a slur or vibrato during it), and the tremolo's strokes
  step_ = stepBase * (f / hzOnset);
  fNow = f;
  // the dynamic: the velocity's, or the Dynamics control's as it moves
  if (!released) dyn = sustainDyn();
  // the body and corrections follow the pitch (past 3 cents: their detail is 50), the dynamic and Body.
  // Before the rotations are set: a pitch falling past kFMax / K adds a harmonic, which must turn
  // at its own frequency from this step on.
  if (!released) {
    const bool moved = std::fabs(f / specHz - 1.f) > kRecomputeRatio;
    const bool dynMoved = std::fabs(dyn - placeDyn) > kDynRecompute || std::fabs(pWeight - placeWeight) > kDynRecompute / kWeightLayers
                          || std::fabs(pPos - placePos) > 0.005f
                          || std::fabs(pEven - placeEven) > 0.01f;
    if (moved || dynMoved) place(f);
    if (moved || dynMoved || pBody != specBody || std::fabs(pSize / specSize - 1.f) > kRecomputeRatio
        || std::fabs(pMute - specMute) > 0.005f) spectrum(f);
  }
  setRotation(f);
  stepBank(f);
}

// Vibrato: after its delay it comes in over its attack; its rate and depth wander a little. Its depth
// follows the string the note is on. Stepped once per kGrid.
float StringsVoice::vibratoC(double midi) {
  float vibC = 0;
  if (pVibDepth > 0 || vibPh != 0) {
    // from the note's start, or its last slur (a new finger: the vibrato starts again)
    const float ts = static_cast<float>(t - vibT0) / sr;
    const float dl = vibSlurred ? kVibSlurDelay * pVibDelay : pVibDelay;
    const float at = vibSlurred ? kVibSlurAttack * pVibAttack : pVibAttack;
    float e = dsp::clamp((ts - dl) / at, 0.f, 1.f);
    e = e * e * (3 - 2 * e);
    vibR += vibA * (vrng.bipolar() * 1.7320508f - vibR);
    vibD += vibA * (vrng.bipolar() * 1.7320508f - vibD);
    const int str = curString;
    const float want = std::exp2((dsp::clamp(static_cast<float>(midi) - kOpen[str], 0.f, 30.f) - kVibRefSemis) / 12.f);
    vibScale += 0.1f * (want - vibScale);   // a string or position change: over a few ms
    const float wantDepth = pVibDepth * vibScale * e * std::max(0.f, 1.f + kVibVaryDepth * pVibVary * vibD * vibNormVary);
    // follows quickly: at a slur it falls to nothing as the finger lifts, without a jump in pitch
    vibDepth += (1.f - std::exp(-kGrid / (kVibFollowS * sr))) * (wantDepth - vibDepth);
    const float depth = vibDepth;
    if (vibRephase && depth < 0.3f) {   // faded: the next cycle starts from the note's centre
      vibPh = 0;
      vibRephase = false;
    }
    const float rate = pVibRate * std::max(0.25f, 1.f + kVibVaryRate * pVibVary * vibR * vibNormVary);
    if (depth > 1e-4f || e > 0 || vibPh != 0) {
      vibPh += dsp::kTwoPi * rate * kGrid / sr;
      if (vibPh > dsp::kTwoPi) vibPh -= dsp::kTwoPi;
      vibC = depth * std::sin(vibPh);
    }
  }
  return vibC;
}

// The bank's step at pitch f: the release or the glide to the targets, the noise pulse's tables, and
// each rotator aimed at its harmonic's level with the body's fine detail.
void StringsVoice::stepBank(float f) {
  // the body's fine detail, at this step's pitch; in from the hand-off with the glide, so the bank
  // starts exactly as the recording is
  float fineW = 0;
  if (bankOn) {
    if (released) {
      float rel = 1.f / pRelease;
      for (int k = 0; k < K; ++k) amp[k] *= fastExp(relRate[k] * rel * kGrid);
    } else if (bowOff >= 0) {
      // a long stroke, the bow still on: it fades as its take did until the bow leaves
      const float g = fastExp(strokeFade * kGrid);
      for (int k = 0; k < K; ++k) amp[k] *= g;
    } else if (t >= tX1) {
      // the first glide from the onset's harmonics is slow (as measured); after it, changes of the
      // dynamic or the pitch's place are followed quickly
      const bool first = t < tX1 + static_cast<long>(3 * kGlideS * sr);
      float g = 1.f - std::exp(-(first ? glideRate : followRate) * kGrid);
      for (int k = 0; k < K; ++k) amp[k] += g * (target[k] - amp[k]);
    }
    fineW = t <= tX1 ? 0.f : 1.f - std::exp(-glideRate * static_cast<float>(t - tX1));
  }
  // the noise's pulse: harder near the bridge, airy (less of it) over the fingerboard
  const float grainWant = pGrain * (1.f + 0.5f * std::max(0.f, pPos)) * (1.f - 0.6f * std::max(0.f, -pPos));
  if (!released && std::fabs(grainWant - grainAmount) > 0.01f) grainShape(grainWant);
  // Each rotator carries its harmonic's amplitude. Aim it at this step's amp × gain × fine detail by a
  // growth per sample folded into its rotation: a smooth (exponential) ramp across the step, at no
  // cost per sample, since a staircase would spread every harmonic into sidebands at the step's rate.
  // Re-aimed every step from where it is, so rounding never drifts.
  if (bankOn) {
    const float l2f = std::log2(f * pSize);
    const float fineK = fineW * pBody * kLog2_10_20;
    const float kNyq = 0.45f * sr / f;   // a harmonic glided up past this would fold over
    // The fine detail moves energy between the harmonics and keeps the total, at once, every step: the
    // level's normalisation rides on amp, which follows slowly, and a slur sweeping the harmonics
    // through the detail faster than that bumped the level by 4 dB. (A judgment: a vibrato's own swing
    // of the whole level, about 2 dB, goes with it; each harmonic's swing stays.)
    float fineNorm = 0;
    if (fineK != 0) {
      float num = 0, den = 0;
      for (int k = 0; k < K; ++k) {
        fineL2[k] = fineK * fineDbLog2(l2f + kLog2K.v[k]);
        float a = amp[k] * gain[k], g = fastExp2(fineL2[k]);
        den += a * a;
        num += a * a * g * g;
      }
      fineNorm = num > 0 && den > 0 ? 0.5f * fastLog2(den / num) : 0.f;
    }
    for (int k = 0; k < K; ++k) {
      float m2 = zr[k] * zr[k] + zi[k] * zi[k];
      float d = (k + 1) > kNyq ? 1e-12f : std::max(amp[k] * gain[k], 1e-12f);
      float fine = fineK != 0 ? fineL2[k] + fineNorm : 0.f;
      float lr = dsp::clamp((0.5f * fastLog2(d * d / std::max(m2, 1e-30f)) + fine) * (1.f / kGrid), -1.f, 1.f);
      float rho = fastExp2(lr);
      rc[k] *= rho;
      rs[k] *= rho;
    }
  }
}

void StringsVoice::render(VoiceContext& ctx, Buffer& out) {
  pLife = ctx.get(synth.life) * 0.01f;
  pPitch = ctx.get(synth.lifePitch) * 0.01f;
  pFlicker = ctx.get(synth.lifeFlicker) * 0.01f;
  pSpeed = ctx.get(synth.lifeSpeed) * 0.01f;
  pBody = ctx.get(synth.body) * 0.01f;
  pNoiseDb = ctx.get(synth.noise);
  pGrain = ctx.get(synth.grain) * 0.01f;
  pRelease = ctx.get(synth.release) * 0.01f;
  pDynCtl = ctx.choice(synth.dynMode) == 1;
  pDyn = ctx.get(synth.dynamics) * 0.03f;
  pVibDepth = ctx.get(synth.vibDepth);
  pVibRate = ctx.get(synth.vibRate);
  pVibDelay = ctx.get(synth.vibDelay);
  pVibAttack = ctx.get(synth.vibAttack);
  pVibVary = ctx.get(synth.vibVary) * 0.01f;
  pGlide = ctx.get(synth.glide);
  pWeight = ctx.get(synth.weight) * 0.01f;
  pSlur = ctx.get(synth.slur) * 0.01f;
  pTremRate = ctx.get(synth.tremRate);
  pEven = ctx.get(synth.even) * 0.01f;
  pSize = ctx.get(synth.bodySize) * 0.01f;
  pWolf = ctx.get(synth.wolf) * 0.01f;
  pWolfHz = ctx.get(synth.wolfNote);
  pPos = ctx.get(synth.bowPos) * 0.01f;
  pMute = ctx.get(synth.mute) * 0.01f;
  if (pending && !restart) {
    if (art == kPizz) setupPizz(ctx);
    else setup(ctx);
    pending = false;
  }
  const int n = out.frames;
  energy = 0;
  int i = 0;
  while (i < n) {
    // a string played again: once what it played has faded, the new note starts from here
    if (restart && fadeLeft <= 0) {
      restart = false;
      vel = nextVel;
      art = nextArt;
      rrSel = nextRR;
      upBow = nextUpBow;
      tremSeed = nextTremSeed;
      seedNoise = nextSeeds[0]; seedWander = nextSeeds[1]; seedVib = nextSeeds[2];
      released = false;
      bankOn = false;
      t = 0;
      if (art == kPizz) setupPizz(ctx);
      else setup(ctx);
      pending = false;
    }
    i = art == kPizz ? pizzRun(ctx, out, i, n) : arcoRun(ctx, out, i, n);
  }

  // the string this note is on is stopped by the finger: its open modes don't ring along
  if (alive) synth.stopMask |= 1u << curString;
  if (!restart) {
    if (art == kPizz) pizzEnd(n);
    else arcoEnd(n);
  }
}

// The bowed note from sample i of this block, until its end or a string played again has faded.
int StringsVoice::arcoRun(VoiceContext& ctx, Buffer& out, int i, int n) {
  const float trim = dsp::dbToGain(kTrimDb);
  const float noiseLevel = dsp::dbToGain(pNoiseDb + std::max(0.f, pPos) * kPosNoiseBridgeDb
                                         + std::max(0.f, -pPos) * kPosNoiseTastoDb + (pMute > 0 ? muteDb(4000.f) : 0.f));
  const bool trem = art == kTrem;
  while (i < n) {
    if (restart && fadeLeft <= 0) return i;
    // a stroke's bow leaves when the take's did; a key let go before then changes nothing
    if (bowOff >= 0) {
      if (!released && t >= bowOff) {
        released = true;
        // the take's own release where it's faster than the notes' pooled one (relRate, from place():
        // the staccatos' tails were 6.6 dB too bright at 1-2 kHz on it), never slower (a low
        // fundamental's half-second fit, beating and ringing along, rang on at 10 dB/s)
        for (int k = 0; k < K; ++k) relRate[k] = std::min(relRate[k], strokeRel[k]);
      }
    }
    else if (releasing && !released) {
      released = true;
      if (art == kTrem) tremEnd();
    }
    if (t % kGrid == 0) {
      // start the bank at the crossfade, its phases set so that each harmonic meets the recording's
      // at tC. A note let go before it still hands over: the string rings on after the bow leaves,
      // from the level the onset has decayed to.
      if (!bankOn && t + kGrid > tX0) {
        float hz = static_cast<float>(ctx.pitchHz());
        for (int k = 0; k < K; ++k) {
          double ph = handPh[k] - static_cast<double>(k + 1) * dsp::kTwoPi * hz / sr * static_cast<double>(tC - t);
          amp[k] = hand[k] * (released ? onsetRel : 1.f);
          float a = std::max(amp[k], 1e-12f);
          zr[k] = static_cast<float>(a * std::cos(ph));
          zi[k] = static_cast<float>(a * std::sin(ph));
        }
        bankOn = true;
      }
      step(ctx);
    }
    int seg = std::min(n - i, kGrid - static_cast<int>(t % kGrid));
    if (restart) seg = std::max(1, std::min(seg, fadeLeft));
    const float lvl = std::exp(kLn10_20 * levelDb) * noiseLevel;
    for (int s = 0; s < seg; ++s, ++i) {
      long ti = t + s;
      // crossfade weight of the model (raised cosine over [tX0, tX1])
      float mw = ti <= tX0 ? 0.f : ti >= tX1 ? 1.f : 0.5f - 0.5f * std::cos(dsp::kPi * (ti - tX0) / float(tX1 - tX0));
      float y = 0;
      // a slur's dip, across the step
      const float art = artPrev + (artGain - artPrev) * (static_cast<float>(ti % kGrid) * (1.f / kGrid));
      // the tremolo's strokes, until the release has taken over
      if (trem && mw < 1) {
        if (!tremStop && ti >= tremNext) tremStroke(ti);
        y += (1 - mw) * tremSample(ti);
      }
      // the onset recording
      if (onset && mw < 1) {
        int ip = static_cast<int>(pos);
        if (ip + 2 < onsetLen) {
          float fr = static_cast<float>(pos - ip);
          float xm = ip > 0 ? onset[ip - 1] : 0.f, x0 = onset[ip], x1 = onset[ip + 1], x2 = onset[ip + 2];
          float c1 = 0.5f * (x1 - xm), c2 = xm - 2.5f * x0 + 2 * x1 - 0.5f * x2, c3 = 0.5f * (x2 - xm) + 1.5f * (x0 - x1);
          y += (1 - mw) * onsetGain * onsetRel * (((c3 * fr + c2) * fr + c1) * fr + x0);
        }
        pos += step_;
        if (released && bowOff < 0) onsetRel *= onsetRelMul;   // a stroke's recording holds its own end
      }
      // the harmonics, and where the fundamental is in its period (for the noise's pulse)
      float th = 0;
      if (bankOn) {
        float h = 0;
        for (int k = 0; k < K; ++k) {
          h += zr[k];
          float r = zr[k] * rc[k] - zi[k] * rs[k];
          zi[k] = zr[k] * rs[k] + zi[k] * rc[k];
          zr[k] = r;
        }
        y += mw * h;
      }
      y *= art;
      // bow noise: follows the model in, pulses with the string, stops quickly when the bow leaves
      if (!released) noiseDrive = mw;
      else noiseDrive *= noiseRelMul;
      if (noiseDrive > 1e-5f) {
        if (bankOn) th = std::atan2(zi[0], zr[0]);   // the rotator's angle: its amplitude doesn't matter
        float x = (th < 0 ? th + dsp::kTwoPi : th) * (kGrainTable / dsp::kTwoPi);
        int j = std::min(static_cast<int>(x), kGrainTable - 1);
        float fj = x - j;
        // each band its own noise: driven by one, neighbouring bands' outputs would be correlated
        // and partly cancel where they overlap (6-13 dB short in places), where tools/make_header.py
        // solves the gains for powers that add
        float nz = 0;
        for (int b = 0; b < cd::kBands; ++b) {
          float e = grain[b][j] + fj * (grain[b][j + 1] - grain[b][j]);
          nz += noiseGain[b] * e * bp[b][1].process(bp[b][0].process(rng_.bipolar() * 1.7320508f));
        }
        y += noiseDrive * lvl * nz;
      }
      y *= trim;
      if (restart) y *= static_cast<float>(fadeLeft - s) / fadeLen;
      out.add(i, y);
      energy += y * y;
    }
    t += seg;
    if (restart) fadeLeft -= seg;
  }

  return i;
}

// A bowed note ends once it has been let go and has rung down.
void StringsVoice::arcoEnd(int n) {
  if (!released || (art == kTrem && !bankOn)) return;
  float sum = 0;
  for (int k = 0; k < K && bankOn; ++k) sum += amp[k] * amp[k];
  float onsetLeft = (onset && t < tX1) ? onsetRel * dsp::dbToGain(-20.f) : 0.f;
  float lv = 0.5f * sum + onsetLeft * onsetLeft + noiseDrive * noiseDrive * 1e-3f;
  if (lv < dsp::dbToGain(2 * kEndDb) && energy / n < dsp::dbToGain(2 * kEndDb)) alive = false;
}

// --- Pizzicato -------------------------------------------------------------------------------------

namespace {
// Where a pitch falls among the plucked notes: the lower one and the way to the next.
void pizzBracket(double midi, int& lo, float& t) {
  if (midi <= pd::noteMidi[0]) { lo = 0; t = 0; return; }
  if (midi >= pd::noteMidi[pd::kNotes - 1]) { lo = pd::kNotes - 2; t = 1; return; }
  lo = 0;
  while (lo < pd::kNotes - 2 && midi >= pd::noteMidi[lo + 1]) ++lo;
  t = static_cast<float>((midi - pd::noteMidi[lo]) / (pd::noteMidi[lo + 1] - pd::noteMidi[lo]));
}
// How fast a note falls over its first second (dB/s), between the plucked notes (in log); above C5
// on along the top interval's slope (a shorter string rings shorter), at most twice C5's.
float pizzDecayAt(double midi) {
  constexpr int top = pd::kNotes - 1;
  if (midi > pd::noteMidi[top]) {
    const float sl = std::log(pd::decayNote[top] / pd::decayNote[top - 1]) / (pd::noteMidi[top] - pd::noteMidi[top - 1]);
    return pd::decayNote[top] * std::min(2.f, std::exp(std::max(0.f, sl) * static_cast<float>(midi - pd::noteMidi[top])));
  }
  int lo; float t;
  pizzBracket(midi, lo, t);
  return pd::decayNote[lo] * std::pow(pd::decayNote[lo + 1] / pd::decayNote[lo], t);
}
float pizzEvenAt(double midi) {
  int lo; float t;
  pizzBracket(midi, lo, t);
  return pd::levelEven[lo] + t * (pd::levelEven[lo + 1] - pd::levelEven[lo]);
}
}  // namespace

// A plucked note: the nearest measured note's take (its round robin), its onset transposed to this
// pitch and its modes moved with it; the modes decay at the take's rates, scaled to how fast a note
// at this pitch falls.
void StringsVoice::setupPizz(VoiceContext& ctx) {
  vrng.seed(seedVib);
  const double midi = ctx.pitch();
  const float hz = static_cast<float>(ctx.pitchHz());
  midiNow = midi;
  int on = 0;
  for (int i = 1; i < pd::kNotes; ++i)
    if (std::fabs(midi - pd::noteMidi[i]) < std::fabs(midi - pd::noteMidi[on])) on = i;
  const int cell = on * pd::kRR + rrSel % pd::kRR;
  pOnset = pd::onset[cell];
  pFRec = pd::f0[on][rrSel % pd::kRR];
  pL2Rec = std::log2(pFRec);
  const float ratio = hz / pFRec;
  stepBase = step_ = ratio * pd::kOnsetRate / sr;
  hzOnset = hz;
  pos = 0;
  tX0 = static_cast<long>(pd::kTOn * pd::kOnsetRate / step_);
  tX1 = static_cast<long>((pd::kTOn + pd::kXf) * pd::kOnsetRate / step_);
  tC = static_cast<long>(pd::kTC * pd::kOnsetRate / step_);
  // the level: velocity² as the library maps it; Even Notes moves it to a smooth curve along the keys
  const float evenDb = pEven * (pizzEvenAt(midi) - pd::levelNote[on]);
  const float g = vel * vel * dsp::dbToGain(evenDb);
  onsetGain = g * pd::kOnsetScale;
  onsetRel = 1;
  onsetRelMul = dsp::dbToGain(-kOnsetReleaseDbS / sr);
  // a softer pluck is darker (a judgment)
  pShelfG = dsp::dbToGain(-kPizzShelfDb * (1.f - vel));
  pShelfA = 1.f - std::exp(-dsp::kTwoPi * kPizzShelfHz / sr);
  pShelfZ = 0;
  const float dScale = pizzDecayAt(midi) / pd::decayNote[on];
  pN = pd::modeCount[cell];
  const int m0 = pd::modeStart[cell];
  for (int m = 0; m < pN; ++m) {
    const int j = m0 + m, k = pd::modeK[j];
    const float fm = (k * pFRec * std::exp2(pd::modeCents[j] * (1.f / 1200.f)) + pd::modeDf[j]) * ratio;
    pOm[m] = dsp::kTwoPi * fm / sr;
    pc0[m] = std::cos(pOm[m]);
    ps0[m] = std::sin(pOm[m]);
    pPh[m] = pd::modePh[j];
    pBase[m] = g * dsp::dbToGain(pd::modeDb[j]);
    pAlpha[m] = pd::modeDecay[j] * dScale / kNeperDb / sr;   // nepers per sample
    pL2k[m] = kLog2K.v[std::min(k, cd::kHarm) - 1];
    pRecDb[m] = bodyDbLog2(pL2Rec + pL2k[m]);
    pRecFine[m] = fineDbLog2(pL2Rec + pL2k[m]);
    pTarget[m] = 0;
  }
  // vibrato (the left hand can rock a plucked note too) starts afresh
  string = curString = assigned >= 0 ? assigned : stringFor(midi);
  vibPh = 0;
  vibR = vibD = 0;
  vibDepth = 0;
  vibT0 = 0;
  vibSlurred = vibRephase = false;
  vibScale = std::exp2((dsp::clamp(static_cast<float>(midi) - kOpen[string], 0.f, 30.f) - kVibRefSemis) / 12.f);
  slurC = 0;
  pLevel = 0;
}

// One kGrid step: the vibrato; each mode's decay (and the finger's damping once the key is up); the
// body following the pitch (as the arco's: the fitted body read where the harmonic is now against where
// it was recorded, and the fine detail, normalised so the level stays), the mute; and each rotator
// aimed at its mode's level by a growth per sample folded into its rotation.
void StringsVoice::stepPizz(VoiceContext& ctx) {
  const double midi = ctx.pitch();
  curString = assigned >= 0 ? assigned : stringFor(midi);
  const float f = static_cast<float>(ctx.pitchHz()) * std::exp2(vibratoC(midi) * (1.f / 1200.f));
  midiNow = midi;
  step_ = stepBase * (f / hzOnset);
  if (!bankOn) return;
  const float q = f / hzOnset;
  const float damp = released ? kPizzDampDbS / pRelease / kNeperDb / sr : 0.f;
  const float l2 = std::log2(f * pSize);
  float num = 0, den = 0;
  for (int m = 0; m < pN; ++m) {
    pBase[m] *= fastExp(-(pAlpha[m] + damp) * kGrid);
    const float bd = pBody * bodyDbLog2(l2 + pL2k[m]) - pRecDb[m]
                     + pBody * (fineDbLog2(l2 + pL2k[m]) - pRecFine[m]);
    pTarget[m] = pBase[m] * fastExp(kLn10_20 * bd);
    den += pBase[m] * pBase[m];
    num += pTarget[m] * pTarget[m];
  }
  const float norm = num > 0 ? std::sqrt(den / num) : 1.f;
  float lv = 0;
  for (int m = 0; m < pN; ++m) {
    const float om = pOm[m] * q;
    float d = pTarget[m] * norm;
    if (pMute > 0) d *= fastExp(kLn10_20 * muteDb(om * sr / dsp::kTwoPi));
    if (om > 0.9f * dsp::kPi) d = 0;    // a mode bent up past this would fold over
    lv += d * d;
    // the rotation at this pitch: the start's, turned by the angle the pitch has moved (a series while
    // it's small, as for vibrato; exactly past that: a wide bend made the series' rotation grow, and
    // the note blew up to +718 dB), and kept at unit size
    const float x = pOm[m] * (q - 1), x2 = x * x;
    float cx, sx;
    if (std::fabs(x) < 0.25f) {
      cx = 1 - x2 * (0.5f - x2 * (1.f / 24));
      sx = x * (1 - x2 * (1.f / 6 - x2 * (1.f / 120)));
    } else {
      cx = std::cos(x);
      sx = std::sin(x);
    }
    const float un = 1.f / std::sqrt(cx * cx + sx * sx);
    cx *= un;
    sx *= un;
    const float m2 = pzr[m] * pzr[m] + pzi[m] * pzi[m];
    const float lr = dsp::clamp(0.5f * fastLog2(std::max(d * d, 1e-30f) / std::max(m2, 1e-30f)) * (1.f / kGrid), -1.f, 1.f);
    const float rho = fastExp2(lr);
    prc[m] = (pc0[m] * cx - ps0[m] * sx) * rho;
    prs[m] = (ps0[m] * cx + pc0[m] * sx) * rho;
  }
  pLevel = 0.5f * lv;
}

// The plucked note from sample i of this block, until its end or a string played again has faded.
int StringsVoice::pizzRun(VoiceContext& ctx, Buffer& out, int i, int n) {
  const float trim = dsp::dbToGain(kTrimDb);
  while (i < n) {
    if (restart && fadeLeft <= 0) return i;
    if (releasing && !released) released = true;
    if (t % kGrid == 0) {
      // the modes start at the crossfade, each at its phase and level at tC brought back to now
      if (!bankOn && t + kGrid > tX0) {
        const float back = static_cast<float>(tC - t);
        for (int m = 0; m < pN; ++m) {
          const double ph = pPh[m] - static_cast<double>(pOm[m]) * back;
          pBase[m] *= std::exp(std::min(pAlpha[m] * back, 4.f)) * (released ? onsetRel : 1.f);
          const float a = std::max(pBase[m], 1e-12f);
          pzr[m] = static_cast<float>(a * std::cos(ph));
          pzi[m] = static_cast<float>(a * std::sin(ph));
        }
        bankOn = true;
      }
      stepPizz(ctx);
    }
    int seg = std::min(n - i, kGrid - static_cast<int>(t % kGrid));
    if (restart) seg = std::max(1, std::min(seg, fadeLeft));
    for (int s = 0; s < seg; ++s, ++i) {
      const long ti = t + s;
      const float mw = ti <= tX0 ? 0.f : ti >= tX1 ? 1.f : 0.5f - 0.5f * std::cos(dsp::kPi * (ti - tX0) / float(tX1 - tX0));
      float y = 0;
      if (pOnset && mw < 1) {
        const int ip = static_cast<int>(pos);
        if (ip + 2 < pd::kOnsetLen) {
          const float fr = static_cast<float>(pos - ip);
          const float xm = ip > 0 ? pOnset[ip - 1] : 0.f, x0 = pOnset[ip], x1 = pOnset[ip + 1], x2 = pOnset[ip + 2];
          const float c1 = 0.5f * (x1 - xm), c2 = xm - 2.5f * x0 + 2 * x1 - 0.5f * x2, c3 = 0.5f * (x2 - xm) + 1.5f * (x0 - x1);
          y += (1 - mw) * onsetGain * onsetRel * (((c3 * fr + c2) * fr + c1) * fr + x0);
        }
        pos += step_;
        if (released) onsetRel *= onsetRelMul;
      }
      if (bankOn) {
        float h = 0;
        for (int m = 0; m < pN; ++m) {
          h += pzr[m];
          const float r = pzr[m] * prc[m] - pzi[m] * prs[m];
          pzi[m] = pzr[m] * prs[m] + pzi[m] * prc[m];
          pzr[m] = r;
        }
        y += mw * h;
      }
      // a softer pluck is darker: a first-order high shelf
      pShelfZ += pShelfA * (y - pShelfZ);
      y = pShelfZ + pShelfG * (y - pShelfZ);
      y *= trim;
      if (restart) y *= static_cast<float>(fadeLeft - s) / fadeLen;
      out.add(i, y);
      energy += y * y;
    }
    t += seg;
    if (restart) fadeLeft -= seg;
  }
  return i;
}

// A plucked note ends once it has rung down, held or not.
void StringsVoice::pizzEnd(int n) {
  if (!bankOn) return;
  const float onsetLeft = (pOnset && t < tX1) ? onsetRel * dsp::dbToGain(-20.f) : 0.f;
  if (pLevel + onsetLeft * onsetLeft < dsp::dbToGain(2 * kEndDb) && energy / n < dsp::dbToGain(2 * kEndDb)) alive = false;
}

